/// Result of [`compute_chrome_layout`]: the rectangles for each workspace
/// region within the horizontal `main` band. Hidden regions are `None` and
/// consume no width.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
struct ChromeLayout {
    activity: Option<Rect>,
    primary_side: Option<Rect>,
    secondary_side: Option<Rect>,
    /// The editor + terminal column (always present).
    right: Rect,
    /// Column of the seam between the editor and the primary side bar, where a
    /// resize drag starts. `None` when the primary side bar is hidden.
    sidebar_splitter_x: Option<u16>,
}

/// Pure horizontal layout of the workspace chrome within `main`. Column order
/// follows the primary side bar's position (the activity bar always flanks the
/// primary side bar on its outer edge, like VS Code):
///   `Left`:  `[activity][primary][right......][secondary]`
///   `Right`: `[secondary][right......][primary][activity]`
/// The `right` column is guaranteed at least `RIGHT_PANE_MIN` cells; the
/// primary side bar is shrunk to make room when the frame is narrow.
fn compute_chrome_layout(
    main: Rect,
    activity_visible: bool,
    primary_visible: bool,
    secondary_visible: bool,
    side_bar_position: SideBarPosition,
    sidebar_w: u16,
    secondary_w: u16,
) -> ChromeLayout {
    let activity_w = if activity_visible {
        ACTIVITY_BAR_WIDTH
    } else {
        0
    };
    let secondary_w = if secondary_visible { secondary_w } else { 0 };
    // Reserve activity + secondary first, then fit the primary side bar in
    // what's left while keeping RIGHT_PANE_MIN for the editor column.
    let reserved = activity_w.saturating_add(secondary_w);
    let after_reserved = main.width.saturating_sub(reserved);
    let max_primary = after_reserved.saturating_sub(RIGHT_PANE_MIN);
    let primary_w = if primary_visible {
        sidebar_w.min(max_primary)
    } else {
        0
    };
    let right_w = after_reserved.saturating_sub(primary_w);

    let row = |x: u16, w: u16| Rect {
        x,
        y: main.y,
        width: w,
        height: main.height,
    };
    let mut x = main.x;
    let (activity, primary_side, right, secondary_side, splitter);
    match side_bar_position {
        SideBarPosition::Left => {
            activity = (activity_w > 0).then(|| row(x, activity_w));
            x += activity_w;
            primary_side = (primary_w > 0).then(|| row(x, primary_w));
            x += primary_w;
            let right_rect = row(x, right_w);
            // Seam = editor's left edge.
            splitter = (primary_w > 0).then_some(right_rect.x);
            right = right_rect;
            x += right_w;
            secondary_side = (secondary_w > 0).then(|| row(x, secondary_w));
        }
        SideBarPosition::Right => {
            secondary_side = (secondary_w > 0).then(|| row(x, secondary_w));
            x += secondary_w;
            let right_rect = row(x, right_w);
            right = right_rect;
            x += right_w;
            // Seam = sidebar's left edge (= editor's right edge).
            splitter = (primary_w > 0).then_some(x);
            primary_side = (primary_w > 0).then(|| row(x, primary_w));
            x += primary_w;
            activity = (activity_w > 0).then(|| row(x, activity_w));
        }
    }
    ChromeLayout {
        activity,
        primary_side,
        secondary_side,
        right,
        sidebar_splitter_x: splitter,
    }
}

/// Pure horizontal placement of the bottom panel within its `band`. `Center`
/// and `Justify` fill the band; `Left`/`Right` hug that half (clamped to a
/// usable minimum). The leftover strip is painted with the editor background
/// by the caller so it never ghosts.
fn panel_band_rect(band: Rect, alignment: PanelAlignment) -> Rect {
    match alignment {
        PanelAlignment::Center | PanelAlignment::Justify => band,
        PanelAlignment::Left => Rect {
            width: (band.width / 2).max(RIGHT_PANE_MIN).min(band.width),
            ..band
        },
        PanelAlignment::Right => {
            let w = (band.width / 2).max(RIGHT_PANE_MIN).min(band.width);
            Rect {
                x: band.x + band.width - w,
                width: w,
                ..band
            }
        }
    }
}

/// Centered popup geometry for frames of any size. Min bounds cap at the
/// frame because Ord::clamp panics on min > max, and a frame with no
/// cells on an axis gets no popup at all.
fn fallback_popup_rect(full: Rect, max_w_cap: u16) -> Rect {
    if full.width == 0 || full.height == 0 {
        return Rect {
            width: 0,
            height: 0,
            ..full
        };
    }
    let max_w = max_w_cap.min(full.width);
    let max_h = full.height;
    let width = (full.width.saturating_mul(7) / 10).clamp(40.min(max_w), max_w);
    let height = (full.height.saturating_mul(6) / 10).clamp(10.min(max_h), max_h);
    Rect {
        x: full.x + (full.width.saturating_sub(width)) / 2,
        y: full.y + (full.height.saturating_sub(height)) / 4,
        width,
        height,
    }
}

fn activity_icon_glyph_x(bar: Rect) -> u16 {
    bar.x + bar.width / 2
}

/// Rank an executable basename as an lldb-dap candidate, or `None` if it is not
/// one. LLVM ships the adapter under several names: the bare `lldb-dap`, the
/// versioned `lldb-dap-18` that Debian/Ubuntu install (often with no
/// unversioned symlink), and the legacy `lldb-vscode[-NN]` name from older
/// releases. Higher rank wins: an unversioned binary (tracks the system
/// default) beats any versioned one, a newer LLVM release beats an older one,
/// and at equal version the modern `lldb-dap` name beats legacy `lldb-vscode`.
fn lldb_dap_rank(name: &str) -> Option<i64> {
    if name == "lldb-dap" {
        return Some(i64::MAX);
    }
    if name == "lldb-vscode" {
        return Some(i64::MAX - 1);
    }
    // `family` breaks ties at equal version: lldb-dap (1) over lldb-vscode (0).
    let (version, family) = name
        .strip_prefix("lldb-dap-")
        .map(|v| (v, 1))
        .or_else(|| name.strip_prefix("lldb-vscode-").map(|v| (v, 0)))?;
    let version: i64 = version.parse().ok()?;
    Some(version * 2 + family)
}

/// Resolve the `lldb-dap` adapter binary: the Xcode Command Line Tools copy
/// first (always present on a dev Mac), then the best-ranked match found by
/// scanning `PATH` for `lldb-dap`/`lldb-dap-NN`/`lldb-vscode[-NN]`. `None` if
/// none is installed.
fn lldb_dap_path() -> Option<String> {
    let xcode = "/Library/Developer/CommandLineTools/usr/bin/lldb-dap";
    if std::path::Path::new(xcode).is_file() {
        return Some(xcode.to_string());
    }
    let path_var = std::env::var_os("PATH")?;
    let mut best: Option<(i64, String)> = None;
    for dir in std::env::split_paths(&path_var) {
        let Ok(entries) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let Some(name) = entry.file_name().to_str().map(str::to_owned) else {
                continue;
            };
            let Some(rank) = lldb_dap_rank(&name) else {
                continue;
            };
            let full = entry.path();
            if is_executable_file(&full) && best.as_ref().is_none_or(|(r, _)| rank > *r) {
                best = Some((rank, full.to_string_lossy().into_owned()));
            }
        }
    }
    best.map(|(_, p)| p)
}

/// The error shown when no lldb-dap adapter is installed, with a host-correct
/// install hint: Xcode Command Line Tools on macOS, the LLVM package elsewhere.
fn lldb_dap_missing_message() -> String {
    let hint = if cfg!(target_os = "macos") {
        "install Xcode Command Line Tools"
    } else {
        "install LLVM, e.g. apt install lldb"
    };
    format!("lldb-dap not found ({hint})")
}

/// The interpreter that runs a Python project's own code: its `.venv` python
/// (where the project's deps, pytest included, are importable) or the system
/// python3. The debug venv's python is only the debugpy ADAPTER host — the
/// debuggee must be this one, or a pytest module launch can't import pytest.
fn project_python(root: &Path) -> PathBuf {
    let venv = root.join(".venv").join("bin").join("python");
    if venv.is_file() {
        return venv;
    }
    if let Some(path_var) = std::env::var_os("PATH") {
        for dir in std::env::split_paths(&path_var) {
            let candidate = dir.join("python3");
            if candidate.is_file() {
                return candidate;
            }
        }
    }
    PathBuf::from("python3")
}

/// Whether `path` is a regular file with the executable bit set — i.e. a
/// compiled binary or script croft can run directly (`./file`) and debug via
/// lldb-dap without a build step. The honest signal for "directly executable",
/// since such files usually have no extension.
fn is_executable_file(path: &Path) -> bool {
    use std::os::unix::fs::PermissionsExt;
    std::fs::metadata(path)
        .map(|m| m.is_file() && m.permissions().mode() & 0o111 != 0)
        .unwrap_or(false)
}

/// Append variable rows to the debug tree, recursing into any expanded
/// (`variablesReference` in `expanded`) container whose children are loaded.
/// Pulled out as a free function so it can borrow the session immutably while
/// the caller mutates the row vector.
fn push_variable_rows(
    rows: &mut Vec<crate::widgets::run_debug::DebugRow>,
    session: &crate::dap::session::DapSession,
    expanded: &std::collections::HashSet<i64>,
    vars: &[crate::dap::session::Variable],
    indent: u8,
) {
    use crate::widgets::run_debug::{DebugRow, DebugRowKind};
    for v in vars {
        let expandable = v.variables_ref > 0;
        let is_open = expandable && expanded.contains(&v.variables_ref);
        rows.push(DebugRow {
            indent,
            kind: DebugRowKind::Variable {
                reference: v.variables_ref,
                expandable,
                expanded: is_open,
                name: v.name.clone(),
                value: v.value.clone(),
                type_name: v.type_name.clone(),
            },
        });
        if is_open && let Some(children) = session.variables.get(&v.variables_ref) {
            push_variable_rows(rows, session, expanded, children, indent.saturating_add(1));
        }
    }
}

fn activity_explorer_y(bar: Rect) -> u16 {
    bar.y + 1
}

fn activity_search_y(bar: Rect) -> u16 {
    activity_explorer_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_source_control_y(bar: Rect) -> u16 {
    activity_search_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_run_debug_y(bar: Rect) -> u16 {
    activity_source_control_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_remote_y(bar: Rect) -> u16 {
    activity_run_debug_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_extensions_y(bar: Rect) -> u16 {
    activity_remote_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_testing_y(bar: Rect) -> u16 {
    activity_extensions_y(bar) + ACTIVITY_ICON_HEIGHT + ACTIVITY_ICON_GAP
}

fn activity_explorer_block(bar: Rect) -> Rect {
    Rect {
        x: bar.x,
        y: activity_explorer_y(bar),
        width: bar.width,
        height: ACTIVITY_ICON_HEIGHT,
    }
}

