    /// VS Code "Change All Occurrences" (Cmd/Ctrl+F2): select every textual
    /// match of the word under the cursor in the current file as multi-cursor
    /// carets so the next keystrokes edit them all at once.
    fn start_change_all_occurrences(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        let n = self.editor.select_all_occurrences_of_word_at_cursor();
        if n == 0 {
            self.status = String::from("No symbol under cursor");
        } else {
            self.status = format!("Selected {n} occurrences (type to replace, Esc to cancel)");
        }
    }

    /// VS Code "Add Selection to Next Find Match" (`Cmd+D`): select the word
    /// under the cursor, then grow the multi-cursor one occurrence per press.
    fn start_select_next_occurrence(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        let n = self.editor.select_next_occurrence();
        if n == 0 {
            self.status = String::from("No symbol under cursor");
        } else if n > 1 {
            self.status = format!("Selected {n} occurrences (type to replace, Esc to cancel)");
        }
    }

    /// VS Code "Delete Line" (`Cmd+Shift+K`): delete the cursor's line, or
    /// every line a selection touches, yanking the removed text to the
    /// clipboard. Replaces the old `Cmd+d d` convenience, whose leader now
    /// belongs to Add Selection to Next Match.
    fn delete_current_line(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        let yanked = self.editor.delete_caret_lines();
        if !yanked.is_empty() {
            copy_to_clipboard(&yanked);
        }
        let n = yanked.lines().count();
        self.status = format!("Deleted {n} {}", if n == 1 { "line" } else { "lines" });
    }

    /// VS Code "Rename Symbol" (F2): prompt for a new name pre-filled with the
    /// identifier under the cursor; committing fires an LSP `rename` request.
    fn start_rename_symbol(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        let Some(path) = self.editor.path.clone() else {
            self.status = String::from("No file open");
            return;
        };
        let row = self.editor.cursor_row;
        let col = self.editor.cursor_col;
        let Some((start, end)) = self.editor.word_at(row, col) else {
            self.status = String::from("No symbol under cursor");
            return;
        };
        if self.lsp.is_none() {
            self.status = String::from("No language server for this file");
            return;
        }
        let word: String = self.editor.lines[row]
            .chars()
            .skip(start)
            .take(end - start)
            .collect();
        self.prompt = Some(Prompt {
            label: format!("Rename Symbol '{word}'"),
            buffer: word,
            kind: PromptKind::RenameSymbol { path, row, col },
            target_dir: PathBuf::new(),
            error: None,
        });
    }

    pub fn drain_lsp_rename(&mut self) -> bool {
        let mut arrived = false;
        let mut edits: Option<Vec<(PathBuf, Vec<crate::widgets::editor::TextSpanEdit>)>> = None;
        {
            let Some(lsp) = self.lsp.as_ref() else {
                return false;
            };
            while let Some(result) = lsp.drain_rename() {
                if Some(result.request_id) != self.rename_request_id {
                    continue;
                }
                arrived = true;
                edits = result.edits;
            }
        }
        if !arrived {
            return false;
        }
        self.rename_request_id = None;
        match edits {
            Some(files) => match self.apply_rename_edits(&files) {
                Ok((file_count, occ)) => {
                    self.status =
                        format!("Renamed {occ} occurrence(s) across {file_count} file(s)");
                }
                Err(e) => self.status = format!("Rename failed: {e}"),
            },
            None => self.status = String::from("Rename produced no changes"),
        }
        true
    }

    /// Apply an LSP rename `WorkspaceEdit` (already normalised to per-file
    /// char-indexed spans). Open tabs are edited in-memory as one undo step
    /// and left dirty; closed files are rewritten on disk (the fs watcher
    /// refreshes the tree). Returns (files touched, occurrences replaced).
    fn apply_rename_edits(
        &mut self,
        files: &[(PathBuf, Vec<crate::widgets::editor::TextSpanEdit>)],
    ) -> Result<(usize, usize)> {
        let mut file_count = 0;
        let mut occ_count = 0;
        for (path, edits) in files {
            if edits.is_empty() {
                continue;
            }
            if let Some(n) = self.editor.apply_rename_to_open_tab(path, edits) {
                occ_count += n;
            } else if self.is_collab_guest() && collab_file_key(&self.tree.root, path).is_some() {
                // Closed-file rename edits are raw disk writes; a collab
                // guest never writes shared files (open tabs above are fine:
                // those edits flow to the owner as ops).
                continue;
            } else {
                let content = std::fs::read_to_string(path)?;
                let mut lines: Vec<String> = content.split('\n').map(str::to_string).collect();
                occ_count += crate::widgets::editor::apply_span_edits_to_lines(&mut lines, edits);
                std::fs::write(path, lines.join("\n"))?;
            }
            file_count += 1;
        }
        Ok((file_count, occ_count))
    }

    /// VS Code "Format Document" (Cmd+Opt+Shift+F): ask the language server to
    /// reformat the active buffer. No-op on read-only diff / sheet / image
    /// tabs. The reply is applied in [`drain_lsp_format`].
    fn start_format_document(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        let Some(path) = self.editor.path.clone() else {
            self.status = String::from("No file open");
            return;
        };
        let Some(lsp) = self.lsp.as_mut() else {
            self.status = String::from("No language server for this file");
            return;
        };
        // Mirror the editor's indentation preference; servers that carry their
        // own config (rustfmt, ruff, prettier) ignore these but the fields are
        // required by the LSP request.
        let (tab_size, insert_spaces) = self.editor.indent_preference();
        let id = lsp.request_formatting(path, tab_size, insert_spaces);
        self.format_request_id = Some(id);
        self.status = String::from("Formatting document");
    }

    pub fn drain_lsp_format(&mut self) -> bool {
        let mut arrived = false;
        let mut edits: Option<Vec<crate::widgets::editor::TextSpanEdit>> = None;
        let mut unsupported = false;
        let mut path: Option<PathBuf> = None;
        {
            let Some(lsp) = self.lsp.as_ref() else {
                return false;
            };
            while let Some(result) = lsp.drain_formatting() {
                if Some(result.request_id) != self.format_request_id {
                    continue;
                }
                arrived = true;
                edits = result.edits;
                unsupported = result.unsupported;
                path = Some(result.path);
            }
        }
        if !arrived {
            return false;
        }
        self.format_request_id = None;
        if unsupported {
            self.status = String::from("No formatter available for this file");
            self.complete_pending_save();
            return true;
        }
        match (edits, path) {
            (Some(edits), Some(path)) if !edits.is_empty() => {
                match self.editor.apply_rename_to_open_tab(&path, &edits) {
                    Some(_) => {
                        self.editor.clamp_cursor();
                        self.status = String::from("Formatted document");
                    }
                    None => self.status = String::from("Format failed: document not open"),
                }
            }
            _ => self.status = String::from("Document already formatted"),
        }
        // A format-on-save write is deferred until now so the disk file gets the
        // formatted text in one go.
        self.complete_pending_save();
        true
    }

    /// VS Code "Quick Fix" (`Cmd+.`): ask the language server for the code
    /// actions available at the cursor (with the diagnostics on that line as
    /// context) and present them in a picker. No-op on read-only preview tabs.
    /// The reply is handled in [`Self::drain_lsp_code_actions`].
    /// The Quick Fix picker for a merge conflict at the cursor: VS Code's
    /// three accept actions, applied locally with no LSP involvement.
    fn open_merge_conflict_picker(&mut self) {
        use crate::widgets::list_picker::{ListPicker, ListPurpose, ListRow};
        let rows = vec![
            ListRow {
                id: String::from("current"),
                label: String::from("Accept Current Change"),
            },
            ListRow {
                id: String::from("incoming"),
                label: String::from("Accept Incoming Change"),
            },
            ListRow {
                id: String::from("both"),
                label: String::from("Accept Both Changes"),
            },
        ];
        self.open_list_picker(
            ListPicker::new(ListPurpose::MergeConflict, "Resolve Merge Conflict", rows),
            "No merge conflict at the cursor",
        );
    }

    /// Resolve the merge conflict at the cursor, reporting VS Code's
    /// wording in the status line. Backs both the palette's Merge Conflict
    /// commands and the Quick Fix picker rows.
    fn resolve_merge_at_cursor(&mut self, res: crate::merge::Resolution) {
        // Palette commands reach here on any tab; a non-text view (image,
        // sheet, diff) must refuse rather than consult the conflict cache.
        if !self.editor_is_text() {
            self.status = String::from("Merge conflict actions need a text file");
            return;
        }
        let row = self.editor.cursor_row;
        if !self.editor.resolve_conflict_at(row, res) {
            self.status = String::from("No merge conflict at the cursor");
            return;
        }
        self.status = String::from(match res {
            crate::merge::Resolution::Current => "Accepted current change",
            crate::merge::Resolution::Incoming => "Accepted incoming change",
            crate::merge::Resolution::Both => "Accepted both changes",
        });
    }

    fn start_code_action(&mut self) {
        if self.editor.diff.is_some() || self.editor.sheet.is_some() || self.editor.image.is_some()
        {
            return;
        }
        // A merge conflict at the cursor takes the Quick Fix over LSP code
        // actions, like VS Code's Accept Current / Incoming / Both lenses:
        // resolving markers is what the user wants there, and it needs no
        // server round-trip.
        let cursor_row = self.editor.cursor_row;
        if crate::merge::conflict_containing(self.editor.conflicts(), cursor_row).is_some() {
            self.open_merge_conflict_picker();
            return;
        }
        let Some(path) = self.editor.path.clone() else {
            self.status = String::from("No file open");
            return;
        };
        let row = self.editor.cursor_row as u32;
        let col = self.editor.cursor_col as u32;
        let diagnostics = self.editor.diagnostics_in_line_range(row, row);
        let Some(lsp) = self.lsp.as_mut() else {
            self.status = String::from("No language server for this file");
            return;
        };
        let id = lsp.request_code_action(path, row, col, row, col, diagnostics);
        self.code_action_request_id = Some(id);
        self.code_action_pending_resolve = false;
        self.status = String::from("Finding quick fixes");
    }

    pub fn drain_lsp_code_actions(&mut self) -> bool {
        let mut arrived = false;
        let mut items: Option<Vec<crate::lsp::manager::CodeActionItem>> = None;
        let mut unsupported = false;
        {
            let Some(lsp) = self.lsp.as_ref() else {
                return false;
            };
            while let Some(result) = lsp.drain_code_action() {
                if Some(result.request_id) != self.code_action_request_id {
                    continue;
                }
                arrived = true;
                items = result.items;
                unsupported = result.unsupported;
            }
        }
        if !arrived {
            return false;
        }
        self.code_action_request_id = None;
        let was_resolve = std::mem::take(&mut self.code_action_pending_resolve);
        if unsupported {
            self.status = String::from("No quick fixes: no code-action server for this file");
            return true;
        }
        // A resolve reply carries the one action the user already chose, now with
        // its edit filled in: apply it directly instead of re-opening a menu.
        if was_resolve {
            match items.and_then(|mut v| v.pop()) {
                Some(item) => self.apply_resolved_code_action(item),
                None => self.status = String::from("Quick fix could not be resolved"),
            }
            return true;
        }
        match items {
            Some(items) if items.len() == 1 && items[0].needs_resolve => {
                // A single resolve-only action (e.g. a deferred auto-import):
                // resolve it straight away rather than popping a one-row menu.
                self.resolve_and_apply_code_action(items.into_iter().next().unwrap());
            }
            Some(items) if !items.is_empty() => self.open_code_action_picker(items),
            _ => self.status = String::from("No quick fixes available here"),
        }
        true
    }

    /// Present the available code actions in the shared list picker, tagging
    /// each row with its index into `pending_code_actions`.
    fn open_code_action_picker(&mut self, items: Vec<crate::lsp::manager::CodeActionItem>) {
        use crate::widgets::list_picker::{ListPicker, ListPurpose, ListRow};
        let rows = items
            .iter()
            .enumerate()
            .map(|(i, item)| ListRow {
                id: i.to_string(),
                label: if item.is_preferred {
                    format!("{} (preferred)", item.title)
                } else {
                    item.title.clone()
                },
            })
            .collect();
        self.pending_code_actions = items;
        self.open_list_picker(
            ListPicker::new(ListPurpose::CodeAction, "Quick Fix", rows),
            "No quick fixes available here",
        );
    }

    /// Apply the chosen code action: edits first (as one undo step, like rename),
    /// then any command. A resolve-only action is sent for resolution first; its
    /// resolved edit/command arrives back through [`Self::drain_lsp_code_actions`].
    fn apply_code_action(&mut self, item: crate::lsp::manager::CodeActionItem) {
        if item.needs_resolve {
            self.resolve_and_apply_code_action(item);
            return;
        }
        self.apply_resolved_code_action(item);
    }

    /// Apply an action that already carries its edit / command (the leaf of both
    /// the direct and the post-resolve paths). Never re-resolves, so a server
    /// that returns a still-edit-less action after resolve can't loop.
    fn apply_resolved_code_action(&mut self, item: crate::lsp::manager::CodeActionItem) {
        let mut applied = false;
        if !item.edits.is_empty() {
            match self.apply_rename_edits(&item.edits) {
                Ok((files, occ)) => {
                    applied = true;
                    self.status = format!(
                        "{}: changed {occ} edit(s) across {files} file(s)",
                        item.title
                    );
                }
                Err(e) => {
                    self.status = format!("Quick fix failed: {e}");
                    return;
                }
            }
        }
        if let Some(cmd) = item.command
            && let (Some(path), Some(lsp)) = (self.editor.path.clone(), self.lsp.as_mut())
        {
            lsp.execute_command(path, cmd.command, cmd.arguments);
            applied = true;
            self.status = format!("Applied quick fix: {}", item.title);
        }
        if !applied {
            self.status = format!("Quick fix had no effect: {}", item.title);
        }
    }

    /// Send a resolve-only action for `codeAction/resolve`; the resolved item
    /// comes back as a single-item reply that the drain applies.
    fn resolve_and_apply_code_action(&mut self, item: crate::lsp::manager::CodeActionItem) {
        let Some(action) = item.resolve_action else {
            self.status = format!("Quick fix cannot be resolved: {}", item.title);
            return;
        };
        let Some(path) = self.editor.path.clone() else {
            return;
        };
        let Some(lsp) = self.lsp.as_mut() else {
            return;
        };
        let id = lsp.request_code_action_resolve(path, item.server, action);
        self.code_action_request_id = Some(id);
        self.code_action_pending_resolve = true;
        self.status = String::from("Resolving quick fix");
    }

    /// Route the key through the completion popup when one is open.
    /// Up/Down navigate, Enter/Tab accept and replace the typed prefix
    /// with the chosen completion's full text, Esc dismisses. Printable
    /// chars and Backspace pass through to the editor and refresh the
    /// popup's filter prefix in place; if no items match the new prefix
    /// the popup dismisses on the next tick.
    fn handle_completion_popup_key(&mut self, key: KeyEvent) -> bool {
        if self.completion_popup.is_none() {
            return false;
        }
        match key.code {
            KeyCode::Up => {
                if let Some(p) = self.completion_popup.as_mut() {
                    p.move_up();
                }
                true
            }
            KeyCode::Down => {
                if let Some(p) = self.completion_popup.as_mut() {
                    p.move_down();
                }
                true
            }
            KeyCode::Enter | KeyCode::Tab => {
                let prefix_len = self
                    .completion_popup
                    .as_ref()
                    .map(|p| p.prefix.chars().count())
                    .unwrap_or(0);
                let text = self
                    .completion_popup
                    .as_ref()
                    .and_then(|p| p.selected_label());
                let is_snippet = self
                    .completion_popup
                    .as_ref()
                    .is_some_and(|p| p.selected_is_snippet());
                self.completion_popup = None;
                self.completion_request_id = None;
                if let Some(t) = text {
                    if is_snippet {
                        // The body carries $1/$0 tab stops; expand_snippet
                        // removes the typed prefix itself and drives the caret.
                        self.editor.expand_snippet(&t, prefix_len);
                    } else {
                        for _ in 0..prefix_len {
                            self.editor.backspace();
                        }
                        self.editor.insert_str(&t);
                    }
                }
                true
            }
            KeyCode::Esc => {
                self.completion_popup = None;
                self.completion_request_id = None;
                true
            }
            KeyCode::Backspace => {
                self.editor.backspace();
                self.refresh_completion_prefix();
                true
            }
            KeyCode::Char(c) => {
                if key.modifiers.contains(KeyModifiers::CONTROL)
                    || key.modifiers.contains(KeyModifiers::ALT)
                    || key.modifiers.contains(KeyModifiers::SUPER)
                {
                    self.completion_popup = None;
                    self.completion_request_id = None;
                    return false;
                }
                self.editor.insert_char(c);
                self.refresh_completion_prefix();
                if !is_word_continuation(c) {
                    self.completion_popup = None;
                    self.completion_request_id = None;
                }
                if is_signature_help_trigger(c) {
                    self.trigger_signature_help();
                }
                true
            }
            _ => {
                self.completion_popup = None;
                self.completion_request_id = None;
                false
            }
        }
    }

    fn refresh_completion_prefix(&mut self) {
        let prefix = self.editor.word_before_cursor();
        let Some(popup) = self.completion_popup.as_mut() else {
            return;
        };
        popup.set_prefix(prefix);
        if popup.visible_is_empty() {
            self.completion_popup = None;
            self.completion_request_id = None;
        }
    }

    fn drain_fs_events(&mut self) -> bool {
        let init_changed = self.try_install_pending_init();
        let drain = self.fs_watch.drain(&mut self.tree, &self.editor);
        if drain.dirs_changed {
            self.refresh_git_status_debounced();
            if drain.finder_relevant {
                self.kick_file_finder_index_rebuild();
            }
        }
        // `touched_open_file` only tracks the ACTIVE tab; a background tab's
        // file change still arrives as a watcher event (got_any), so sweep
        // every tab whenever any event lands. The sweep is stamp-based, so
        // a benign Access/Metadata event that didn't move mtime+len is a
        // no-op and won't clobber selection or reload spuriously.
        if drain.got_any {
            self.reload_open_file_after_external_change();
        }
        let polled = self.poll_filesystem_changes();
        drain.got_any || init_changed || polled
    }

    fn cycle_focus(&mut self) {
        // Skip hidden panes when cycling.
        let mut next = self.focus;
        for _ in 0..3 {
            next = match next {
                Pane::Tree => Pane::Editor,
                Pane::Editor => Pane::Terminal,
                Pane::Terminal => Pane::Tree,
            };
            if self.pane_visible(next) {
                break;
            }
        }
        // Through `focus_pane`, never a bare assignment: every route into a
        // pane shares its guarantees (terminal find/copy-mode teardown, and
        // restoring the editor from under a maximized terminal).
        self.focus_pane(next);
    }

    /// Returns true exactly once after the welcome OSC-1337 image has been
    /// emitted and the editor pane has stopped being blank (i.e. a file is
    /// now open). The caller — the main draw loop — must respond by
    /// invalidating the prev buffer so ratatui repaints every cell on the
    /// next draw, wiping iTerm's image cache for the welcome region.
    pub fn consume_welcome_image_clear(&mut self) -> bool {
        let opened_file = !self.editor.is_blank_initial();
        self.overlays.welcome.consume_clear_or(opened_file)
    }

    fn render_welcome(&mut self, frame: &mut ratatui::Frame, outer_area: Rect) {
        if outer_area.width == 0 || outer_area.height == 0 {
            return;
        }
        // In iTerm2 image mode we let the iTerm session bg (forced to
        // sRGB(EDITOR_BG_RGB) by `SetColors=bg=srgb:…` at startup) show
        // through the welcome cells via SGR 49 (default bg). The OSC-1337
        // PNG canvas is filled with the same sRGB hex, so both surfaces
        // display the same physical pixel — no Generic-RGB vs sRGB seam.
        // Outside iTerm we fall back to explicit truecolor since there's
        // no PNG to match against.
        let bg = if crate::iterm2_inline::detect_iterm2_inline_support() {
            Style::default().bg(Color::Reset)
        } else {
            Style::default().bg(self.theme.editor_bg())
        };
        // Paint a full bordered box around the welcome area so the editor
        // pane has the same visible envelope as when a file is open
        // (Borders::ALL on the editor widget). Without this, the welcome
        // bg bleeds into the tree, the terminal, and the window edge with
        // no perceptible seam — and the sidebar splitter looks
        // unreachable. The bg style is applied to the same block so the
        // inside is filled in one pass. The welcome content then renders
        // into `block.inner(outer_area)` so a tall recents list can never
        // paint over the border rows.
        let outer_block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(Color::DarkGray))
            .style(bg);
        let area = outer_block.inner(outer_area);
        frame.render_widget(outer_block, outer_area);
        if area.width == 0 || area.height == 0 {
            return;
        }
        // Layout-control icons at the welcome screen's top-right, inside the
        // border row — same controls as the editor tab strip (placement A).
        let icon_row = Rect {
            x: outer_area.x + 1,
            y: outer_area.y,
            width: outer_area.width.saturating_sub(2),
            height: 1,
        };
        self.paint_layout_icons(frame, icon_row);

        // Layout regions, top-to-bottom:
        //   [logo + version badge]
        //   [tagline]
        //   [gradient box: header + release highlights]
        //   [footer chevron line]
        let block_left = area.x + area.width / 8;
        let block_right = area.x + area.width - area.width / 8;
        let block_w = block_right.saturating_sub(block_left);
        // The gradient box's content area is 2 cells narrower (the box
        // border itself).
        let inner_w = block_w.saturating_sub(2);
        let has_recent_panel = self.welcome.has_recent_panel();
        let recents_inner_h = welcome_recents_height(self.welcome.notes(), inner_w);
        let tagline_h = 1u16;
        let footer_h = 1u16;
        // Gaps: blank row after logo, after tagline, after box.
        let gaps_h = 3u16;

        let logo_max_w = (area.width as u32).saturating_sub(4) as u16;
        let logo_w_cells = logo_max_w.clamp(8, 48);
        // Pick the logo height first, then size the recents box to fit
        // whatever's left. Without this a tall commit list would extend the
        // stack past the bottom of the welcome area and we'd panic painting
        // into rows that don't exist (ratatui buffers are fixed-size).
        let logo_h_cells = area
            .height
            .saturating_sub(tagline_h + footer_h + gaps_h)
            .clamp(4, 14);
        let used_above_box = logo_h_cells + 1 + tagline_h + 1; // logo, gap, tagline, gap
        let used_below_box = 1 + footer_h; // gap, footer
        let max_box_h = area
            .height
            .saturating_sub(used_above_box)
            .saturating_sub(used_below_box);
        // Box content needs at least the 4-cell border+inset envelope to be
        // worth drawing.
        let desired_box_h = if has_recent_panel {
            recents_inner_h.saturating_add(4)
        } else {
            0
        };
        let box_h = desired_box_h.min(max_box_h);

        let total_h = used_above_box + box_h + used_below_box;
        let block_top = area.y + area.height.saturating_sub(total_h) / 2;
        let logo_x = area.x + area.width.saturating_sub(logo_w_cells) / 2;
        let logo_y = block_top;
        let area_max_y = area.y + area.height;

        let desired = WelcomeLayout {
            cell_x: logo_x,
            cell_y: logo_y,
            cell_w: logo_w_cells,
            cell_h: logo_h_cells,
        };

        // Re-bake the OSC-1337 image whenever the layout shifts (resize,
        // sidebar toggle, font size change). The canvas is filled with the
        // raw `EDITOR_BG_RGB` bytes interpreted as sRGB (iTerm2 decodes
        // PNG bytes as sRGB by default). The pane's SGR-painted cells use
        // `Color::Reset` so they fall back to the iTerm session bg, which
        // we force to the same sRGB hex via `SetColors=bg=srgb:…` at
        // startup. Both surfaces therefore display the same physical
        // pixel pair-for-pair.
        if !self.overlays.welcome.layout_matches(&desired) {
            self.overlays.welcome.request_clear_if_displayed();
            if let Some((cw, ch)) = self.cell_pixel {
                let canvas_w = (logo_w_cells as u32) * cw;
                let canvas_h = (logo_h_cells as u32) * ch;
                let bg = self.theme_bg_pixel();
                let protocol = self.inline_protocol;
                if let Ok(baked) = crate::iterm2_inline::fit_image(
                    crate::iterm2_inline::WELCOME_LOGO_PNG,
                    canvas_w,
                    canvas_h,
                    bg,
                ) && let Some(raw) = crate::iterm2_inline::build_inline_image(
                    protocol,
                    &baked,
                    logo_w_cells,
                    logo_h_cells,
                    false,
                    crate::iterm2_inline::KITTY_ID_WELCOME,
                ) {
                    let osc = crate::iterm2_inline::maybe_tmux_wrap(
                        protocol,
                        crate::iterm2_inline::detect_tmux(),
                        raw,
                    );
                    self.overlays.welcome.set_image(osc);
                }
            }
            self.overlays.welcome.set_layout(desired);
            self.overlays.welcome.mark_dirty();
        }

        if !self.overlays.welcome.has_image() {
            // Text fallback for non-iTerm2 terminals.
            let label = " croft ";
            let lx = logo_x
                .saturating_add(logo_w_cells.saturating_sub(label.chars().count() as u16) / 2);
            let ly = logo_y + logo_h_cells / 2;
            frame.buffer_mut().set_string(
                lx,
                ly,
                label,
                Style::default()
                    .fg(Color::Rgb(0x9d, 0xa5, 0xb4))
                    .add_modifier(Modifier::BOLD),
            );
        }

        // Version badge to the right of the wordmark (the wordmark sits
        // in the lower portion of the logo PNG; the badge tracks that row).
        let version_label = format!(" v{} ", env!("CARGO_PKG_VERSION"));
        let version_w = version_label.chars().count() as u16;
        let badge_x = logo_x + logo_w_cells + 1;
        let badge_y = logo_y + (logo_h_cells * 5) / 6;
        if badge_x + version_w + 2 <= area.x + area.width && badge_y + 2 < area_max_y {
            let badge_style = Style::default()
                .fg(rgb_color(GRAD_TL))
                .add_modifier(Modifier::BOLD);
            frame
                .buffer_mut()
                .set_string(badge_x, badge_y, "\u{256d}", badge_style);
            for i in 0..version_w {
                frame
                    .buffer_mut()
                    .set_string(badge_x + 1 + i, badge_y, "\u{2500}", badge_style);
            }
            frame.buffer_mut().set_string(
                badge_x + 1 + version_w,
                badge_y,
                "\u{256e}",
                badge_style,
            );
            frame
                .buffer_mut()
                .set_string(badge_x, badge_y + 1, "\u{2502}", badge_style);
            frame.buffer_mut().set_string(
                badge_x + 1,
                badge_y + 1,
                &version_label,
                Style::default()
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
            );
            frame.buffer_mut().set_string(
                badge_x + 1 + version_w,
                badge_y + 1,
                "\u{2502}",
                badge_style,
            );
            frame
                .buffer_mut()
                .set_string(badge_x, badge_y + 2, "\u{2570}", badge_style);
            for i in 0..version_w {
                frame.buffer_mut().set_string(
                    badge_x + 1 + i,
                    badge_y + 2,
                    "\u{2500}",
                    badge_style,
                );
            }
            frame.buffer_mut().set_string(
                badge_x + 1 + version_w,
                badge_y + 2,
                "\u{256f}",
                badge_style,
            );
        }

        // Tagline.
        let tagline_y = logo_y + logo_h_cells + 1;
        let tagline_w = WELCOME_TAGLINE.chars().count() as u16;
        let tagline_x = area.x + area.width.saturating_sub(tagline_w) / 2;
        if tagline_y < area_max_y && tagline_w <= area.width {
            frame.buffer_mut().set_string(
                tagline_x,
                tagline_y,
                WELCOME_TAGLINE,
                Style::default().fg(Color::Rgb(0x88, 0xc0, 0xd0)),
            );
        }

        let box_y = tagline_y + tagline_h + 1;
        if has_recent_panel && box_h >= 4 && block_w >= 4 && box_y + box_h <= area_max_y {
            let box_rect = Rect {
                x: block_left,
                y: box_y,
                width: block_w,
                height: box_h,
            };
            paint_gradient_box(frame.buffer_mut(), box_rect);

            // Inner content area: 1-cell inset from each border.
            let inner_x = box_rect.x + 2;
            let inner_y = box_rect.y + 1;
            let inner_w_actual = box_rect.width.saturating_sub(4);

            let row_style = Style::default().fg(Color::Rgb(0xc5, 0xcd, 0xd9));

            // Header row: "> IN THIS RELEASE (vX.Y.Z)". The leading chevron
            // echoes the cr<>ft wordmark's bracket. The highlights below are
            // hand-curated data baked into this build (see
            // `crate::release_notes`), so the heading names the exact version.
            let header_y = inner_y;
            frame.buffer_mut().set_string(
                inner_x,
                header_y,
                "> ",
                Style::default()
                    .fg(rgb_color(GRAD_TR))
                    .add_modifier(Modifier::BOLD),
            );
            frame.buffer_mut().set_string(
                inner_x + 2,
                header_y,
                format!("IN THIS RELEASE (v{})", env!("CARGO_PKG_VERSION")),
                Style::default()
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
            );

            // Each highlight: a kind glyph in the gutter (rocket = new feature,
            // bug = fix) tinted by kind, then the wrapped one-line summary.
            // Continuation lines align under the summary, leaving the gutter
            // clear so the glyph reads as a single bullet.
            let summary_x = inner_x + WELCOME_NOTE_GUTTER;
            let summary_w = inner_w_actual.saturating_sub(WELCOME_NOTE_GUTTER);
            let last_row = box_rect.y + box_rect.height - 1;
            let mut row_y = header_y + 2;
            for note in self.welcome.notes() {
                if row_y >= last_row {
                    break;
                }
                frame.buffer_mut().set_string(
                    inner_x,
                    row_y,
                    note.kind.icon(),
                    Style::default()
                        .fg(note.kind.color())
                        .add_modifier(Modifier::BOLD),
                );
                let lines = wrapped_welcome_note_summary(note, inner_w_actual);
                for (line_idx, line) in lines.iter().enumerate() {
                    let line_y = row_y + line_idx as u16;
                    if line_y >= last_row {
                        break;
                    }
                    let clipped: String = line.chars().take(summary_w as usize).collect();
                    frame
                        .buffer_mut()
                        .set_string(summary_x, line_y, clipped, row_style);
                }
                row_y = row_y.saturating_add(lines.len().max(1) as u16);
            }
        }
    }

    /// Render the secondary side bar (VS Code's auxiliary bar): the active
    /// file's Outline, on the edge opposite the primary side bar. Reuses the
    /// single `OutlinePanel`, forced expanded for this dedicated panel; its
    /// collapse state is saved/restored so the Explorer's own OUTLINE section
    /// (which may render the same widget afterward) keeps its toggle.
    fn render_secondary_side_bar(&mut self, frame: &mut ratatui::Frame, area: Option<Rect>) {
        let Some(area) = area else {
            return;
        };
        if area.width == 0 || area.height == 0 {
            return;
        }
        // A left border + bg fill so the panel reads as a distinct column,
        // like the primary side bar's seam against the editor.
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::LEFT)
            .border_style(Style::default().fg(Color::Rgb(0x2b, 0x2b, 0x2b)))
            .style(Style::default().bg(self.theme.editor_bg()));
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let saved_collapsed = self.outline.collapsed;
        self.outline.collapsed = false;
        self.outline.theme = self.theme;
        self.outline.focus_gradient = self.theme.gradient();
        self.outline.focused = false;
        self.outline.hover_pointer = self.pointer_cell;
        frame.render_widget(&mut self.outline, inner);
        self.outline.collapsed = saved_collapsed;
    }

    /// Paint the three layout-control icons (Toggle Primary Side Bar, Toggle
    /// Panel, Customize Layout) right-aligned on the single-row `row` — the top
    /// of the editor tab strip, or the welcome screen's top edge. croft's
    /// analog of VS Code's title-bar layout controls (placement A). Records the
    /// hit rects in `self.layout_icon_areas`.
    fn paint_layout_icons(&mut self, frame: &mut ratatui::Frame, row: Rect) {
        self.layout_icon_areas = LayoutIconAreas::default();
        let w = LAYOUT_ICON_CELLS_W;
        let stride = w + 1; // one-column gap between icons
        // Three icons + a one-column right pad.
        let needed = stride * 3;
        if row.height == 0 || row.width < needed {
            return;
        }
        let y = row.y;
        let right = row.x + row.width;
        let cust_x = right.saturating_sub(w + 1); // 1-col right pad
        let panel_x = cust_x.saturating_sub(stride);
        let side_x = panel_x.saturating_sub(stride);
        if side_x < row.x {
            return;
        }
        let rect = |x: u16| Rect {
            x,
            y,
            width: w,
            height: LAYOUT_ICON_CELLS_H,
        };
        self.layout_icon_areas = LayoutIconAreas {
            toggle_side_bar: rect(side_x),
            toggle_panel: rect(panel_x),
            customize: rect(cust_x),
        };
        // On an image-capable terminal the post-draw flush paints crisp 2× PNG
        // icons at these cells (see `pending_activity_image_overlays`); the text
        // path below is only the fallback for terminals without inline images.
        if self.overlays.activity.has_images() {
            return;
        }
        let pointer = self.pointer_cell;
        // The codicon shape carries the on/off state (filled vs. hollow), like
        // VS Code; colour brightens to the accent on hover. Glyphs sit centred
        // in the 4-wide slot.
        let base = Color::Rgb(0xcc, 0xcc, 0xcc);
        let accent = Color::Rgb(0x4e, 0x9a, 0xff);
        let mut paint = |x: u16, glyph: char| {
            let hovered = pointer.is_some_and(|(px, py)| py == y && px >= x && px < x + w);
            let color = if hovered { accent } else { base };
            frame.buffer_mut().set_string(
                x + w / 2,
                y,
                glyph.to_string(),
                Style::default().fg(color),
            );
        };
        let side_glyph = if self.show_tree {
            crate::icons::LAYOUT_SIDEBAR_ON
        } else {
            crate::icons::LAYOUT_SIDEBAR_OFF
        };
        let panel_glyph = if self.show_terminal {
            crate::icons::LAYOUT_PANEL_ON
        } else {
            crate::icons::LAYOUT_PANEL_OFF
        };
        paint(side_x, side_glyph);
        paint(panel_x, panel_glyph);
        paint(cust_x, crate::icons::LAYOUT_CUSTOMIZE);
    }

    fn render_activity_bar(&mut self, frame: &mut ratatui::Frame, area: Rect) {
        if area.width == 0 || area.height == 0 {
            return;
        }
        // Keep the per-frame activity badges current before the post-draw flush
        // emits them. Both are count-gated, so a frame with no churn is a cheap
        // no-op. (The SCM badge refreshes off the git worker instead.)
        self.refresh_explorer_unsaved_badge();
        self.refresh_remote_ports_badge();
        self.refresh_testing_badge();
        self.refresh_problems_badge();
        // In images mode the activity bar inherits the iTerm session bg
        // (forced to sRGB(EDITOR_BG_RGB) via SetColors), matching the rest
        // of the panes. The glyph-fallback path keeps a solid bg for
        // terminals that can't render OSC-1337.
        let bg = if self.overlays.activity.has_images() {
            Style::default().bg(Color::Reset)
        } else {
            Style::default().bg(self.theme.editor_bg())
        };
        // In images mode the icon PNG owns the entire activity-bar block —
        // background, codicon, and active pill are baked in. Rendering a bg
        // block here would force a per-cell diff every frame, which in turn
        // would force us to re-emit the OSC-1337 images on every draw. Both
        // are visible to the user. So in images mode we leave the cells
        // untouched and let the post-draw OSC writer paint them once.
        if !self.overlays.activity.has_images() {
            frame.render_widget(ratatui::widgets::Block::default().style(bg), area);
        }
        let active_bar = Color::Rgb(0x4e, 0x9a, 0xff);
        let bg_color = bg.bg.unwrap_or(Color::Reset);
        let explorer_block = activity_explorer_block(area);
        let search_block = activity_search_block(area);
        let source_control_block = activity_source_control_block(area);
        let remote_block = activity_remote_block(area);
        let run_debug_block = activity_run_debug_block(area);
        let extensions_block = activity_extensions_block(area);
        let testing_block = activity_testing_block(area);
        let settings_block = activity_settings_block(area);
        let explorer_active = self.sidebar_view == SidebarView::Explorer;
        let search_active = self.sidebar_view == SidebarView::Search;
        let source_control_active = self.sidebar_view == SidebarView::SourceControl;
        let remote_active = self.sidebar_view == SidebarView::Remote;
        let run_debug_active = self.sidebar_view == SidebarView::RunDebug;
        let extensions_active = self.sidebar_view == SidebarView::Extensions;
        let testing_active = self.sidebar_view == SidebarView::Testing;
        let settings_active = self.settings_menu_active();
        // Hover brightens the glyph (like active) but draws no selection pill,
        // mirroring the image path's hovered variant. Selected wins over hover.
        let hov = self.hovered_activity_icon;
        let explorer_hovered = hov == Some(ActivityIcon::Explorer);
        let search_hovered = hov == Some(ActivityIcon::Search);
        let source_control_hovered = hov == Some(ActivityIcon::SourceControl);
        let remote_hovered = hov == Some(ActivityIcon::Remote);
        let run_debug_hovered = hov == Some(ActivityIcon::RunDebug);
        let extensions_hovered = hov == Some(ActivityIcon::Extensions);
        let testing_hovered = hov == Some(ActivityIcon::Testing);
        let settings_hovered = hov == Some(ActivityIcon::Settings);

        let active_color = Color::White;
        let inactive_color = Color::Rgb(0x6c, 0x7d, 0x9c);
        let glyph_x = activity_icon_glyph_x(area);
        let render_glyph = |frame: &mut ratatui::Frame,
                            block: Rect,
                            glyph: char,
                            is_active: bool,
                            is_hovered: bool| {
            let mid = block.y + block.height.saturating_sub(1) / 2;
            if is_active {
                let pill = Rect {
                    x: block.x,
                    y: mid,
                    width: 1,
                    height: 1,
                };
                frame.render_widget(
                    ratatui::widgets::Paragraph::new("▎")
                        .style(Style::default().fg(active_bar).bg(bg_color)),
                    pill,
                );
            }
            let cell = Rect {
                x: glyph_x,
                y: mid,
                width: 1,
                height: 1,
            };
            let color = if is_active || is_hovered {
                active_color
            } else {
                inactive_color
            };
            frame.render_widget(
                ratatui::widgets::Paragraph::new(glyph.to_string()).style(
                    Style::default()
                        .fg(color)
                        .bg(bg_color)
                        .add_modifier(Modifier::BOLD),
                ),
                cell,
            );
        };
        // Text analogue of the baked count badge for image-less terminals: an
        // accent cell with the count at the icon's bottom-right corner.
        let badge_bg = self.theme.accent();
        let render_count_badge = |frame: &mut ratatui::Frame, block: Rect, count: usize| {
            if count == 0 {
                return;
            }
            let label = if count > 9 {
                String::from("9+")
            } else {
                count.to_string()
            };
            let w = label.chars().count() as u16;
            frame.render_widget(
                ratatui::widgets::Paragraph::new(label).style(
                    Style::default()
                        .fg(Color::White)
                        .bg(badge_bg)
                        .add_modifier(Modifier::BOLD),
                ),
                Rect {
                    x: block.x + block.width.saturating_sub(w),
                    y: block.y + block.height.saturating_sub(1),
                    width: w,
                    height: 1,
                },
            );
        };

        if !self.overlays.activity.has_images() {
            // Glyph fallback path: render the codicon and a separate active
            // pill on the leftmost column. iTerm2's image path bakes the
            // pill into the PNG itself, so this branch is only used on
            // terminals that can't render OSC-1337.
            render_glyph(
                frame,
                explorer_block,
                crate::icons::ACTIVITY_EXPLORER,
                explorer_active,
                explorer_hovered,
            );
            render_count_badge(frame, explorer_block, self.unsaved_count());
            render_glyph(
                frame,
                search_block,
                crate::icons::ACTIVITY_SEARCH,
                search_active,
                search_hovered,
            );
            render_glyph(
                frame,
                source_control_block,
                crate::icons::ACTIVITY_SOURCE_CONTROL,
                source_control_active,
                source_control_hovered,
            );
            let scm_count = if self.git.status().in_repo {
                self.source_control.changes_count()
            } else {
                0
            };
            render_count_badge(frame, source_control_block, scm_count);
            render_glyph(
                frame,
                remote_block,
                crate::icons::ACTIVITY_REMOTE,
                remote_active,
                remote_hovered,
            );
            render_count_badge(frame, remote_block, self.ports.forwarded_count());
            render_glyph(
                frame,
                run_debug_block,
                crate::icons::ACTIVITY_RUN_DEBUG,
                run_debug_active,
                run_debug_hovered,
            );
            render_glyph(
                frame,
                extensions_block,
                crate::icons::ACTIVITY_EXTENSIONS,
                extensions_active,
                extensions_hovered,
            );
            render_glyph(
                frame,
                testing_block,
                crate::icons::ACTIVITY_TESTING,
                testing_active,
                testing_hovered,
            );
            render_count_badge(frame, testing_block, self.testing.failed_count());
            if settings_block.width > 0 {
                render_glyph(
                    frame,
                    settings_block,
                    crate::icons::ACTIVITY_SETTINGS,
                    settings_active,
                    settings_hovered,
                );
            }
        }

        self.sidebar_areas.explorer_icon = explorer_block;
        self.sidebar_areas.search_icon = search_block;
        self.sidebar_areas.source_control_icon = source_control_block;
        self.sidebar_areas.remote_icon = remote_block;
        self.sidebar_areas.run_debug_icon = run_debug_block;
        self.sidebar_areas.extensions_icon = extensions_block;
        self.sidebar_areas.testing_icon = testing_block;
        self.sidebar_areas.settings_icon = settings_block;
    }

    fn set_sidebar_view(&mut self, view: SidebarView) {
        if self.sidebar_view != view {
            self.overlays.activity.mark_dirty();
            // Leaving Search while a scan is in flight: send an
            // empty-query request so the worker cancels the live walker
            // threads instead of letting them keep saturating every core
            // until the scan finishes. The user's hits stay populated for
            // when they come back; only the live work is dropped.
            if self.sidebar_view == SidebarView::Search && view != SidebarView::Search {
                let _ = self
                    .search_query_tx
                    .send(SearchRequest::Query(String::new(), self.search.opts));
            }
            // Leaving Run-Debug after the headline icon was on screen:
            // arm a one-shot `terminal.clear()` so iTerm2 evicts the
            // cached OSC-1337 image cells. Plain SGR overwrites do not
            // reliably evict those cells, but `\x1b[2J` (which
            // `terminal.clear()` emits) does — same gate the welcome
            // wordmark and editor preview pipelines use. The post-draw
            // flush function is silent on the non-Run-Debug path, so
            // nothing stomps the freshly-drawn next sidebar.
            if self.sidebar_view == SidebarView::RunDebug
                && view != SidebarView::RunDebug
                && self.overlays.run_debug.was_emitted()
            {
                self.overlays.run_debug.request_clear();
            }
            // Same eviction trick for the Source Control no-repo hero
            // PNG: leaving Source Control after the image was painted
            // would otherwise leave the cached PNG under whatever
            // sidebar replaces it.
            if self.sidebar_view == SidebarView::SourceControl && view != SidebarView::SourceControl
            {
                self.overlays.hero.request_clear_if_displayed();
            }
            // The Source Control commit dropdown is anchored to that view;
            // close it on any view change so it can't linger over the next
            // sidebar.
            self.commit_menu_open = false;
        }
        self.sidebar_view = view;
        if self.sidebar_view == SidebarView::Remote && self.remote.refresh_if_config_changed() {
            self.status = String::from("Reloaded SSH remotes");
        }
        if !self.show_tree {
            self.show_tree = true; // ensure the side panel is open when switching
        }
        match view {
            SidebarView::Explorer => self.focus_pane(Pane::Tree),
            SidebarView::Search => {
                self.focus_pane(Pane::Tree); // tree pane = side panel; dispatch by view
                self.search.select_all_query();
            }
            SidebarView::SourceControl => {
                self.refresh_source_control();
                self.focus_pane(Pane::Tree);
            }
            SidebarView::Remote => self.focus_pane(Pane::Tree),
            SidebarView::RunDebug => {
                self.refresh_run_debug();
                self.focus_pane(Pane::Tree);
            }
            SidebarView::Extensions => {
                self.refresh_extensions();
                self.focus_pane(Pane::Tree);
            }
            SidebarView::Testing => self.focus_pane(Pane::Tree),
        }
    }

    /// Rebuild the Extensions panel's row list from the bundled + user manifests,
    /// stamping each with its live enabled state from prefs. Called whenever the
    /// view is shown or a toggle flips, so the list always reflects the manifests
    /// on disk and the current disable set.
    fn refresh_extensions(&mut self) {
        let items = build_extension_items(&self.disabled_extensions);
        self.extensions.set_items(items);
    }

    fn pane_visible(&self, p: Pane) -> bool {
        match p {
            Pane::Tree => self.show_tree,
            Pane::Terminal => self.show_terminal,
            Pane::Editor => true,
        }
    }

    fn toggle_terminal(&mut self) {
        self.show_terminal = !self.show_terminal;
        // Hiding the terminal must also clear the maximize flag, otherwise
        // the next time the user reopens the terminal it would still hide
        // the editor — which is surprising because Ctrl+J is the user's
        // mental "show my normal layout again" key.
        if !self.show_terminal {
            self.terminal_maximized = false;
        }
        // If we just hid the terminal while it was focused, fall back to editor.
        if !self.show_terminal && self.focus == Pane::Terminal {
            self.focus_pane(Pane::Editor);
        }
        // If we just showed the terminal, optionally jump focus to it for quick use.
        if self.show_terminal {
            self.focus_pane(Pane::Terminal);
        }
    }

    /// `Ctrl+Shift+J`: flip the maximize-terminal flag. When turning ON,
    /// also ensure the terminal pane is visible and focused so the user
    /// can start typing immediately. When turning OFF, re-arm the welcome
    /// wordmark so it re-paints in the restored editor area.
    fn toggle_terminal_maximize(&mut self) {
        self.terminal_maximized = !self.terminal_maximized;
        if self.terminal_maximized {
            if !self.show_terminal {
                self.show_terminal = true;
            }
            self.focus_pane(Pane::Terminal);
            self.overlays.welcome.request_clear_if_displayed();
        } else {
            self.overlays.welcome.mark_dirty();
        }
    }

    pub fn terminal(&self) -> &PtyTerminal {
        &self.terminals[self.active_terminal]
    }

    pub fn terminal_mut(&mut self) -> &mut PtyTerminal {
        &mut self.terminals[self.active_terminal]
    }

    /// Spawn a new PTY-backed terminal next to the existing ones and make
    /// it the active one. The pane becomes visible if it was hidden. The
    /// new terminal's cwd is the *live* cwd of the active terminal's shell
    /// (so a `cd somewhere` inside the user's prompt is reflected), with
    /// the workspace root as a fallback if we can't resolve it.
    ///
    /// The new terminal lands immediately to the right of the currently
    /// active one, not at the far end of the strip, so the user's mental
    /// model of "the new tab sits next to where I was" matches what they
    /// see. Inserting at the end would scatter related splits across the
    /// row whenever the active terminal wasn't already on the right edge.
    pub fn split_terminal(&mut self) -> Result<()> {
        self.insert_terminal(
            PtyTerminal::new(&self.next_terminal_cwd()).context("spawning terminal")?,
        );
        Ok(())
    }

    /// Open a new pane running a specific shell (a terminal profile) instead of
    /// `$SHELL`. Same placement and focus behaviour as [`split_terminal`].
    pub fn split_terminal_with_shell(&mut self, shell_path: &str) -> Result<()> {
        let cwd = self.next_terminal_cwd();
        self.insert_terminal(
            PtyTerminal::new_shell(shell_path, &cwd).context("spawning terminal")?,
        );
        Ok(())
    }

    /// The cwd a new terminal should inherit: the active terminal's live
    /// directory if it has one, else the workspace root.
    fn next_terminal_cwd(&self) -> PathBuf {
        // The shell's own OSC 7 report (shell integration) beats sampling
        // the process table — it is exact and free of proc-inspection
        // races — but only when the REPORTING host is this machine: an
        // in-pane ssh session names a remote path that would silently
        // resolve to the wrong local directory whenever it exists here.
        self.terminal()
            .local_shell_cwd()
            .filter(|p| p.is_dir())
            .or_else(|| {
                self.terminal()
                    .pid()
                    .and_then(cwd_of_pid)
                    .filter(|p| p.is_dir())
            })
            .unwrap_or_else(|| self.workspace_root.clone())
    }

    /// Insert `term` just after the active pane, make it active, and reveal the
    /// terminal pane.
    fn insert_terminal(&mut self, term: PtyTerminal) {
        let target = self.active_terminal + 1;
        self.terminals.insert(target, term);
        self.active_terminal = target;
        if !self.show_terminal {
            self.show_terminal = true;
        }
        self.focus_pane(Pane::Terminal);
        self.save_terminal_session();
    }

    /// Snapshot the terminal panel (pane order, cwds, names, focus) into
    /// the per-workspace session store. Called on structural changes and at
    /// quit; the default single-pane layout prunes the record instead.
    pub fn save_terminal_session(&mut self) {
        let root = self.workspace_root.display().to_string();
        let panes = self
            .terminals
            .iter()
            .map(|t| crate::terminal_session::PaneRecord {
                cwd: t
                    .local_shell_cwd()
                    .filter(|p| p.is_dir())
                    .or_else(|| t.pid().and_then(cwd_of_pid).filter(|p| p.is_dir()))
                    .unwrap_or_else(|| self.workspace_root.clone())
                    .display()
                    .to_string(),
                name: t.manual_name().map(str::to_string),
            })
            .collect();
        let record = crate::terminal_session::SessionRecord {
            panes,
            active: self.active_terminal,
        };
        crate::terminal_session::save_for_root(&self.terminal_session_path, &root, record);
    }

    /// Resurrect this workspace's terminal panel from the session store:
    /// each recorded pane comes back as a fresh shell in its directory
    /// (with its name), and focus returns to the pane that had it. Called
    /// once at startup, replacing the default lone pane. A recorded
    /// directory that no longer exists falls back to the workspace root; a
    /// pane whose shell fails to spawn is skipped.
    pub fn restore_terminal_session(&mut self) {
        let map = crate::terminal_session::load(&self.terminal_session_path);
        let Some(rec) = map.get(&self.workspace_root.display().to_string()) else {
            return;
        };
        let mut terms = Vec::new();
        for p in &rec.panes {
            let dir = PathBuf::from(&p.cwd);
            let dir = if dir.is_dir() {
                dir
            } else {
                self.workspace_root.clone()
            };
            if let Ok(mut t) = PtyTerminal::new(&dir) {
                t.set_manual_name(p.name.clone());
                terms.push(t);
            }
        }
        if terms.is_empty() {
            return;
        }
        self.terminals = terms;
        self.active_terminal = rec.active.min(self.terminals.len() - 1);
        self.sync_focus_flags();
        self.status = format!("Restored terminal session ({} panes)", self.terminals.len());
    }

    /// Available terminal profiles as `(shell_path, label)`: the shells in
    /// `/etc/shells`, with the user's current `$SHELL` ensured present
    /// (prepended) so the default is always an option even on a box with no
    /// `/etc/shells`.
    fn terminal_profiles(&self) -> Vec<(String, String)> {
        let contents = std::fs::read_to_string("/etc/shells").unwrap_or_default();
        let mut shells = crate::widgets::terminal::parse_shells(&contents);
        if let Ok(current) = std::env::var("SHELL")
            && !current.is_empty()
        {
            let base = std::path::Path::new(&current)
                .file_name()
                .and_then(|s| s.to_str())
                .unwrap_or(&current)
                .to_string();
            if !shells.iter().any(|(_, b)| *b == base) {
                shells.insert(0, (current, base));
            }
        }
        shells
    }

    /// Where the profile dropdown hangs: under the `⌄` caret of the pane it was
    /// opened from, with the menu auto-clamping up/left to stay on screen.
    /// Anchoring on the first caret in the vec is wrong twice over — hidden
    /// panes hold `Rect::default()` placeholders so a button's position names
    /// its terminal, and side by side every pane has a live caret, so every
    /// pane's dropdown would hang under the leftmost one. Falls back to the
    /// toolbar's top-right corner before the caret has been painted.
    fn terminal_caret_origin(&self, pane: usize) -> (u16, u16) {
        self.terminal_profile_buttons
            .get(pane)
            .filter(|c| c.width > 0)
            .map(|c| (c.x, c.y.saturating_add(1)))
            .unwrap_or((self.last_frame_area.width.saturating_sub(20), 1))
    }

    /// Open the terminal-profile dropdown (VS Code's `⌄` next to `+`): a compact
    /// context menu anchored under the caret, one row per shell. Picking a row
    /// opens a new pane running that shell.
    fn open_terminal_profile_picker(&mut self, pane: usize) {
        let items: Vec<MenuEntry> = self
            .terminal_profiles()
            .into_iter()
            .map(|(path, label)| MenuEntry::Item {
                label,
                action: MenuAction::NewTerminalWithProfile(path),
            })
            .collect();
        if items.is_empty() {
            self.status = String::from("No terminal profiles found");
            return;
        }
        let origin = self.terminal_caret_origin(pane);
        // The dropdown is anchored under the `⌄` caret in the terminal
        // toolbar and grows downward into the terminal panel — it never
        // overlaps the editor's welcome logo, so the cached OSC-1337 image
        // is left intact rather than evicted (evicting it left the logo
        // blank, since the welcome emit is gated off while a menu is open).
        self.context_menu = Some(ContextMenu {
            origin,
            items,
            selected: 0,
            open_submenu: None,
            submenu_selected: 0,
            target_dir: self.tree.root.clone(),
        });
    }

    /// Clear the terminal at `idx`'s screen and scrollback (Cmd+K K / menu).
    fn clear_terminal_at(&mut self, idx: usize) {
        if let Some(t) = self.terminals.get_mut(idx) {
            t.clear_screen_and_scrollback();
            // The cleared grid invalidates find's state on this pane: the
            // anchored match names content that no longer exists (and the
            // clear can kill the scroll clock's tracer), so navigation
            // restarts from scratch and the count reflects the empty grid.
            if self.terminal_find.is_some() && self.terminal_find_pane == idx {
                self.terminal_find_match = None;
                self.terminals[idx].set_current_match(None, 0);
                let (lines, _top) = self.terminals[idx].grid_lines();
                if let Some(state) = self.terminal_find.as_mut() {
                    state.match_count = crate::widgets::editor_find::count_matches(
                        &lines,
                        &state.query,
                        state.opts,
                    );
                    state.match_index = None;
                }
            }
            self.status = String::from("Cleared terminal");
        }
    }

    /// Open a prompt to rename the terminal pane at `idx` (Cmd+K R / menu),
    /// pre-filled with its current label.
    fn begin_rename_terminal(&mut self, idx: usize) {
        let Some(t) = self.terminals.get(idx) else {
            return;
        };
        let current = t.label().to_string();
        self.prompt = Some(Prompt {
            label: String::from("Rename Terminal"),
            buffer: current,
            kind: PromptKind::RenameTerminal(idx),
            target_dir: PathBuf::new(),
            error: None,
        });
    }

    /// Cmd+K N: open the annotation prompt for the active pane's selection
    /// (its first line's span). When the span overlaps an existing
    /// annotation, the prompt edits that note instead.
    fn begin_annotate_terminal(&mut self) {
        let pane = self.active_terminal;
        // Selection and clock from ONE snapshot: separate reads let PTY
        // output land in between, pairing a pre-output line with a
        // post-output clock and pinning the note to the wrong row.
        let (sel, clock) = self.terminals[pane].selection_and_clock();
        let Some(sel) = sel.filter(|s| s.has_area()) else {
            self.status = String::from("Annotate: select some output first (drag or copy mode)");
            return;
        };
        let (sr, sc, er, ec) = sel.normalised();
        let (_, _, cols, _) = self.terminals[pane].grid_bounds();
        let end = if er > sr { cols.saturating_sub(1) } else { ec };
        let (start, len) = (sc, end.saturating_sub(sc) + 1);
        // Translate the existing annotations at the SAME captured clock as
        // the selection, or output scrolling in between shifts them off the
        // fixed `sr` and the same span duplicates instead of editing.
        let current = self.terminals[pane].annotations_at_clock(clock);
        let existing = current
            .iter()
            .position(|&(l, s0, ln, _)| l == sr && s0 < start + len && start < s0 + ln);
        let buffer = existing
            .and_then(|i| current.get(i).map(|a| a.3.clone()))
            .unwrap_or_default();
        self.prompt = Some(Prompt {
            label: String::from("Annotate Selection"),
            buffer,
            kind: PromptKind::AnnotateTerminal {
                pane,
                line: sr,
                clock,
                start,
                len,
                existing,
            },
            target_dir: PathBuf::new(),
            error: None,
        });
    }

    /// Cmd+K Shift+N: drop every annotation whose span intersects the
    /// selection's first line span.
    fn delete_terminal_annotations_in_selection(&mut self) {
        let pane = self.active_terminal;
        let Some(sel) = self.terminals[pane].selection().filter(|s| s.has_area()) else {
            self.status = String::from("Delete annotation: select over the note first");
            return;
        };
        let (sr, sc, er, ec) = sel.normalised();
        let (_, _, cols, _) = self.terminals[pane].grid_bounds();
        let end = if er > sr { cols.saturating_sub(1) } else { ec };
        let hits: Vec<usize> = self.terminals[pane]
            .annotations_current()
            .iter()
            .enumerate()
            .filter(|&(_, &(l, s0, ln, _))| l == sr && s0 <= end && sc < s0 + ln)
            .map(|(i, _)| i)
            .collect();
        if hits.is_empty() {
            self.status = String::from("No annotation under the selection");
            return;
        }
        for i in hits.into_iter().rev() {
            self.terminals[pane].remove_annotation(i);
        }
        self.status = String::from("Deleted annotation");
    }

    /// Drop the terminal at `idx`. Returns false (and does nothing) when
    /// only one terminal is left or `idx` is out of range. Hiding the pane
    /// is the user's job (Ctrl+J), not ours, so the last terminal stays.
    /// The active index shifts so the same logical terminal remains active
    /// when an inactive pane is closed; closing the active pane reseats the
    /// focus on the neighbour to the left (or the new last if we removed
    /// the right edge).
    ///
    /// The pane is not dropped (which would kill its child): it parks in
    /// `closed_terminals` for [`UNDO_CLOSE_GRACE`] so Cmd+K ⇧T can bring it
    /// back, process and scrollback intact. The tick reaps expired entries.
    pub fn close_terminal_at(&mut self, idx: usize) -> bool {
        if self.terminals.len() <= 1 || idx >= self.terminals.len() {
            return false;
        }
        let term = self.terminals.remove(idx);
        self.closed_terminals.push(ClosedTerminal {
            term,
            idx,
            closed_at: std::time::Instant::now(),
        });
        if self.active_terminal == idx {
            if self.active_terminal >= self.terminals.len() {
                self.active_terminal = self.terminals.len() - 1;
            }
        } else if self.active_terminal > idx {
            self.active_terminal -= 1;
        }
        // A lone terminal has nothing to maximize against; the rail would be
        // empty, so the split view is the honest state.
        if self.terminals.len() <= 1 {
            self.terminal_pane_maximized = false;
            // Safety: never keep broadcast armed against a single pane —
            // the next split would silently start receiving mirrored input.
            if self.broadcast_input {
                self.broadcast_input = false;
                self.status = String::from("Broadcast input off (one pane left)");
            }
        }
        self.sync_focus_flags();
        self.save_terminal_session();
        true
    }

    /// Toggle maximize mode for the active terminal pane (Cmd+K M / the
    /// pane's `⛶` button): one pane spans the panel's width and the other
    /// terminals move to the right rail, where clicking a row hands it the
    /// maximized pane. Orthogonal to `toggle_terminal_maximize`
    /// (Ctrl+Shift+J), which grows the panel over the editor: this
    /// reapportions the panel's width, not the window's rows.
    pub fn toggle_terminal_pane_maximize(&mut self) {
        if self.terminal_pane_maximized {
            self.terminal_pane_maximized = false;
            self.status = String::from("Restored terminal split");
        } else if self.terminals.len() > 1 {
            self.terminal_pane_maximized = true;
            self.status = String::from("Maximized terminal");
        } else {
            self.status = String::from("Only one terminal open");
        }
    }

    /// Drop the rail's hit rects and its column. Both must go together: a
    /// stale area would keep swallowing the wheel after the rail left screen.
    fn clear_terminal_rail(&mut self) {
        self.terminal_rail_rects.clear();
        self.terminal_rail_area = Rect::default();
    }

    /// Paint the maximize-mode rail: one row per terminal down the panel's
    /// right edge — the active one highlighted, the rest hover-lit — so the
    /// user can shuffle between maximized terminals. Records one hit rect
    /// per row in `terminal_rail_rects`, index-aligned with `terminals`.
    fn paint_terminal_rail(&mut self, frame: &mut ratatui::Frame, rail: Rect) {
        self.terminal_rail_area = rail;
        if rail.width == 0 || rail.height == 0 {
            return;
        }
        let brand = self.theme.gradient();
        // Same selected-row treatment as the OPEN EDITORS list, so the rail
        // reads as the same family of chrome in both themes.
        let sel_bg = if brand {
            crate::gradient::rgb_color(crate::gradient::POPUP_SEL_BG)
        } else {
            Color::Rgb(0x09, 0x4d, 0x77)
        };
        // With more terminals than rows the rail is a window over the list,
        // scrolled by the wheel — the panel floors at 3 rows, so four panes
        // are enough to reach this. Switching panes scrolls the new one into
        // view so its highlight is never off-screen, but only on the frame the
        // active pane CHANGES: revealing every frame would pin the window
        // whenever the active pane sits at either end and make the wheel inert.
        let rows = rail.height as usize;
        let max_scroll = self.terminals.len().saturating_sub(rows);
        let mut scroll = self.terminal_rail_scroll.min(max_scroll);
        if self.terminal_rail_revealed != Some(self.active_terminal) {
            if self.active_terminal < scroll {
                scroll = self.active_terminal;
            } else if self.active_terminal >= scroll + rows {
                scroll = self.active_terminal + 1 - rows;
            }
            self.terminal_rail_revealed = Some(self.active_terminal);
        }
        self.terminal_rail_scroll = scroll;
        for i in 0..self.terminals.len() {
            // Rows outside the window still push a placeholder, so a rect's
            // position in the vec keeps naming its terminal. `rect_contains`
            // rejects empty rects, so they can never phantom-match a click.
            if i < scroll || i >= scroll + rows {
                self.terminal_rail_rects.push(Rect::default());
                continue;
            }
            let y = rail.y + (i - scroll) as u16;
            let row = Rect {
                x: rail.x,
                y,
                width: rail.width,
                height: 1,
            };
            let active = i == self.active_terminal;
            let bg = if active {
                Some(sel_bg)
            } else {
                crate::widgets::hover::row_hover_bg(row, self.pointer_cell, brand)
            };
            if let Some(bg) = bg {
                frame.buffer_mut().set_style(row, Style::default().bg(bg));
            }
            let label = self.terminals[i].label().to_string();
            let room = TERMINAL_RAIL_LABEL_W as usize;
            let shown: String = label.chars().take(room).collect();
            let fg = if active {
                Style::default()
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default()
            };
            // `set_string` clips at the buffer edge, not the rail's, so a
            // label wider than a clamped rail would paint its tail over the
            // panel to the right. Clip to the rail's own width.
            frame.buffer_mut().set_stringn(
                row.x,
                y,
                format!(" {TERMINAL_RAIL_ICON} {shown}"),
                row.width as usize,
                fg,
            );
            self.terminal_rail_rects.push(row);
        }
    }

    /// Move the terminal at `from` so it sits at slot `to`, keeping
    /// `active_terminal` pointing at the same terminal it did before. Drives
    /// the drag-reorder of side-by-side panes and maximize-mode rail rows.
    pub fn move_terminal(&mut self, from: usize, to: usize) {
        if from == to || from >= self.terminals.len() || to >= self.terminals.len() {
            return;
        }
        // `last_area` is a SLOT's geometry, but it lives on the terminal
        // object and so travels with it. The panes do not actually move on
        // screen until the next frame, and the drag hit-tests `last_area`
        // between frames — the main loop drains the whole queued mouse burst
        // before drawing. Re-seat the rects in slot order so the next motion
        // report over the same cell resolves to the pane now sitting there
        // instead of swapping the two straight back, which made the final
        // order the parity of however many motion reports arrived.
        let slot_rects: Vec<Rect> = self.terminals.iter().map(|t| t.last_area).collect();
        let t = self.terminals.remove(from);
        self.terminals.insert(to, t);
        self.active_terminal = match self.active_terminal {
            a if a == from => to,
            a if from < a && a <= to => a - 1,
            a if to <= a && a < from => a + 1,
            a => a,
        };
        if self.terminal_pane_maximized {
            // Maximize mode has exactly one live rect, and it belongs to
            // whichever pane was active at the LAST PAINT — not to the dragged
            // terminal, since the press and the drag are drained together. So
            // neither positional rule works here: find the live rect and hand
            // it to the pane the drag leaves active, which is the one that will
            // own the panel on the next frame.
            let pane = slot_rects
                .iter()
                .copied()
                .find(|r| r.width > 0)
                .unwrap_or_default();
            let active = self.active_terminal;
            for (i, term) in self.terminals.iter_mut().enumerate() {
                term.last_area = if i == active { pane } else { Rect::default() };
            }
        } else {
            for (term, rect) in self.terminals.iter_mut().zip(slot_rects) {
                term.last_area = rect;
            }
        }
        self.terminal_session_dirty = true;
    }

    /// Write the pane session if a reorder marked it pending. Called once per
    /// tick so a drag costs one write instead of one per motion report.
    pub fn flush_terminal_session(&mut self) {
        if std::mem::take(&mut self.terminal_session_dirty) {
            self.save_terminal_session();
        }
    }

    /// Drop the currently-active terminal. Thin wrapper kept for the
    /// keyboard shortcut and existing callers.
    pub fn close_active_terminal(&mut self) -> bool {
        self.close_terminal_at(self.active_terminal)
    }

    /// Cmd+K ⇧T: bring back the most recently closed terminal pane while it
    /// is still inside the undo-close grace window. The pane returns to the
    /// slot it occupied (clamped if the layout shrank) and takes focus; its
    /// child process and scrollback were never touched.
    pub fn undo_close_terminal(&mut self) {
        let Some(parked) = self.closed_terminals.pop() else {
            self.status = String::from("No recently closed terminals");
            return;
        };
        let idx = parked.idx.min(self.terminals.len());
        self.terminals.insert(idx, parked.term);
        self.active_terminal = idx;
        if !self.show_terminal {
            self.show_terminal = true;
        }
        self.focus_pane(Pane::Terminal);
        self.sync_focus_flags();
        self.save_terminal_session();
        self.status = format!("Restored terminal {}", self.terminals[idx].label());
    }

    /// Drop parked closed panes whose grace window lapsed (their Drop kills
    /// the child). Called from the drain tick.
    fn reap_closed_terminals(&mut self) {
        self.closed_terminals
            .retain(|p| p.closed_at.elapsed() <= UNDO_CLOSE_GRACE);
    }

    /// Swap the per-host accent rules (config.json reload, and tests).
    pub fn set_host_accents(&mut self, rules: &[crate::prefs::HostAccentRule]) {
        self.host_accents = compile_host_accents(rules);
    }

    /// Palette "Terminal: Toggle Timestamps": show / hide the per-row
    /// arrival-clock gutter on every pane.
    pub fn toggle_terminal_timestamps(&mut self) {
        self.show_terminal_timestamps = !self.show_terminal_timestamps;
        for t in self.terminals.iter_mut() {
            t.show_timestamps = self.show_terminal_timestamps;
        }
        self.status = String::from(if self.show_terminal_timestamps {
            "Terminal timestamps on"
        } else {
            "Terminal timestamps off"
        });
    }

    /// Cmd+K I: toggle broadcast input. Turning it ON goes through a confirm
    /// popup (iTerm2 warns the same way); turning it OFF is immediate.
    fn toggle_broadcast_input(&mut self) {
        if self.broadcast_input {
            self.broadcast_input = false;
            self.status = String::from("Broadcast input off");
            return;
        }
        if self.terminals.len() < 2 {
            self.status =
                String::from("Broadcast input needs at least two terminal panes (Cmd+T splits)");
            return;
        }
        self.pending_broadcast_enable = true;
    }

    fn confirm_pending_broadcast(&mut self) {
        self.pending_broadcast_enable = false;
        self.broadcast_input = true;
        let receiving = self
            .terminals
            .iter()
            .filter(|t| !t.broadcast_excluded)
            .count();
        self.status = format!(
            "Broadcast input ON: keystrokes go to {receiving} panes (Cmd+K I to stop, Cmd+K Shift+I excludes a pane)"
        );
    }

    fn cancel_pending_broadcast(&mut self) {
        self.pending_broadcast_enable = false;
        self.status = String::from("Broadcast input cancelled");
    }

    /// Cmd+K Shift+I: toggle whether the active pane receives broadcast
    /// input. The focused pane always gets its own typing; exclusion only
    /// mutes the mirrored copy while it is unfocused.
    fn toggle_broadcast_exclusion(&mut self) {
        let idx = self.active_terminal;
        let Some(t) = self.terminals.get_mut(idx) else {
            return;
        };
        t.broadcast_excluded = !t.broadcast_excluded;
        let label = t.label().to_string();
        self.status = if self.terminals[idx].broadcast_excluded {
            format!("{label} excluded from broadcast input")
        } else {
            format!("{label} receives broadcast input again")
        };
    }

    /// Paste counterpart of [`Self::write_terminal_key`] (bracketed-paste
    /// aware per pane): normally just the active pane, mirrored to every
    /// non-excluded pane while broadcast is on (the focused pane always
    /// receives its own input).
    fn paste_terminal_input(&mut self, payload: &[u8]) {
        if self.broadcast_input {
            let active = self.active_terminal;
            for (i, t) in self.terminals.iter_mut().enumerate() {
                if i == active || !t.broadcast_excluded {
                    t.paste_input(payload);
                }
            }
        } else {
            self.terminal_mut().paste_input(payload);
        }
    }

    /// Cycle the active terminal forward by one slot, wrapping at the end.
    pub fn cycle_terminal(&mut self) {
        if self.terminals.len() <= 1 {
            return;
        }
        self.active_terminal = (self.active_terminal + 1) % self.terminals.len();
        self.sync_focus_flags();
    }

    /// Cycle the active terminal backward by one slot, wrapping at the
    /// front. Mirror of `cycle_terminal` for the Cmd+[ binding.
    pub fn cycle_terminal_back(&mut self) {
        let n = self.terminals.len();
        if n <= 1 {
            return;
        }
        self.active_terminal = (self.active_terminal + n - 1) % n;
        self.sync_focus_flags();
    }

    /// OR-fold dirty flags across all terminals while clearing each. Use `|`
    /// (not `||`) so every terminal's flag is consumed even after the first
    /// dirty one is found.
    pub fn drain_terminals_dirty(&mut self) -> bool {
        self.terminals
            .iter()
            .fold(false, |acc, t| acc | t.take_dirty())
    }

    /// Like `drain_terminals_dirty` but does not clear the underlying flags.
    /// The main loop uses this to decide whether to coalesce a PTY-only
    /// redraw without losing the signal if it chooses to skip.
    pub fn peek_terminals_dirty(&self) -> bool {
        self.terminals.iter().any(|t| t.peek_dirty())
    }

    /// Total bytes the PTY reader threads have advanced into their grids
    /// since the last redraw. The main loop uses this to bypass the PTY
    /// redraw cap for small interactive echo while keeping bulk streams
    /// capped. Peeks without clearing; `drain_terminals_dirty` resets it.
    pub fn peek_terminals_pending_bytes(&self) -> usize {
        self.terminals.iter().map(|t| t.peek_pending_bytes()).sum()
    }

    fn terminal_at_pos(&self, col: u16, row: u16) -> Option<usize> {
        self.terminals
            .iter()
            .position(|t| rect_contains(t.last_area, col, row))
    }

    fn focus_pane(&mut self, p: Pane) {
        // Leaving the terminal closes its find bar so a stale match highlight
        // never lingers on the grid once input goes elsewhere. Quick-select
        // labels are torn down for the same reason.
        if p != Pane::Terminal && self.terminal_find.is_some() {
            self.close_terminal_find();
        }
        if p != Pane::Terminal && self.terminal_quick_select.is_some() {
            self.close_terminal_quick_select();
        }
        if p != Pane::Terminal && self.terminal_copy_mode.is_some() {
            self.close_terminal_copy_mode();
        }
        // A maximized terminal gives the editor zero rows; focusing the
        // editor is always an intent to use it, so restore it (VS Code's
        // convention when a file is revealed over a maximized panel).
        // `terminal_pane_maximized` (width, among terminal panes) is
        // unrelated and stays.
        if p == Pane::Editor && self.terminal_maximized {
            self.terminal_maximized = false;
        }
        self.focus = p;
        self.sync_focus_flags();
        if self.editor.focused {
            self.poke_cursor();
        }
    }

    fn sync_focus_flags(&mut self) {
        // Quick-select is bound to the pane it opened on; this per-frame
        // invariant covers every gesture that can move `active_terminal`
        // (clicks, chords, pane closes shifting indices) in one place, so
        // stale labels never survive a pane switch to hijack the new pane.
        if self
            .terminal_quick_select
            .as_ref()
            .is_some_and(|st| st.pane != self.active_terminal)
        {
            self.close_terminal_quick_select();
        }
        // Terminal find is pane-bound the same way.
        if self.terminal_find.is_some() && self.terminal_find_pane != self.active_terminal {
            self.close_terminal_find();
        }
        self.tree.focused = self.focus == Pane::Tree && self.sidebar_view == SidebarView::Explorer;
        self.search.focused = self.focus == Pane::Tree && self.sidebar_view == SidebarView::Search;
        self.source_control.focused =
            self.focus == Pane::Tree && self.sidebar_view == SidebarView::SourceControl;
        self.remote.focused = self.focus == Pane::Tree && self.sidebar_view == SidebarView::Remote;
        self.run_debug.focused =
            self.focus == Pane::Tree && self.sidebar_view == SidebarView::RunDebug;
        self.extensions.focused =
            self.focus == Pane::Tree && self.sidebar_view == SidebarView::Extensions;
        self.editor.focused = self.focus == Pane::Editor;
        // Inactive groups are by definition NOT the focused editor group, so
        // their borders never light up even while the editor pane holds focus.
        // `editor` (the active group) carries the highlight.
        for group in self.editor_layout.inactive_groups_mut() {
            group.focused = false;
        }
        let focused_pane = self.focus == Pane::Terminal;
        let active = self.active_terminal;
        for (i, t) in self.terminals.iter_mut().enumerate() {
            t.focused = focused_pane && i == active;
        }
        // Only the Black theme dresses the focused pane in the gradient
        // border; Croft Dark keeps the historical solid-blue highlight.
        let gradient = self.theme.gradient();
        // Every editor in both groups, not just the active one (deref would
        // only hit the active editor): a tab switch or the split group must
        // not resurrect the legacy navy active-tab chip between syncs.
        // The bundled PDF / CSV viewers are gated by the Extensions panel:
        // when disabled, the editor opens those file types as plain text.
        let pdf_on = self.is_extension_enabled("pdf");
        let csv_on = self.is_extension_enabled("csv");
        for ed in self.editor.editors.iter_mut() {
            ed.focus_gradient = gradient;
            ed.theme = self.theme;
            ed.pdf_viewer_enabled = pdf_on;
            ed.csv_viewer_enabled = csv_on;
        }
        for group in self.editor_layout.inactive_groups_mut() {
            for ed in group.editors.iter_mut() {
                ed.focus_gradient = gradient;
                ed.theme = self.theme;
                ed.pdf_viewer_enabled = pdf_on;
                ed.csv_viewer_enabled = csv_on;
            }
        }
        self.tree.focus_gradient = gradient;
        self.tree.theme = self.theme;
        self.search.focus_gradient = gradient;
        self.search.theme = self.theme;
        self.source_control.focus_gradient = gradient;
        self.source_control.theme = self.theme;
        self.run_debug.focus_gradient = gradient;
        let explorer_focused =
            self.focus == Pane::Tree && self.sidebar_view == SidebarView::Explorer;
        self.outline.focus_gradient = gradient;
        self.outline.theme = self.theme;
        self.outline.focused = explorer_focused;
        self.open_editors.focus_gradient = gradient;
        self.open_editors.theme = self.theme;
        self.open_editors.focused = explorer_focused;
        self.timeline.focus_gradient = gradient;
        self.timeline.theme = self.theme;
        self.timeline.focused = explorer_focused;
        self.commit_graph.focus_gradient = gradient;
        self.commit_graph.theme = self.theme;
        self.commit_graph.focused =
            self.focus == Pane::Tree && self.sidebar_view == SidebarView::SourceControl;
        self.dependencies.focus_gradient = gradient;
        self.dependencies.theme = self.theme;
        self.dependencies.focused = explorer_focused;
        self.remote.focus_gradient = gradient;
        self.remote.theme = self.theme;
        self.extensions.theme = self.theme;
        self.problems.focus_gradient = gradient;
        self.problems.theme = self.theme;
        self.problems.focused = self.focus == Pane::Terminal;
        self.problems.hover_pointer = self.pointer_cell;
        self.output.focus_gradient = gradient;
        self.output.theme = self.theme;
        self.output.focused = self.focus == Pane::Terminal;
        self.output.hover_pointer = self.pointer_cell;
        self.output.sync();
        self.ports.focus_gradient = gradient;
        self.ports.theme = self.theme;
        self.ports.focused = self.focus == Pane::Terminal;
        self.ports.hover_pointer = self.pointer_cell;
        for t in self.terminals.iter_mut() {
            t.show_timestamps = self.show_terminal_timestamps;
        }
        self.captures.focus_gradient = gradient;
        self.captures.theme = self.theme;
        self.captures.focused = self.focus == Pane::Terminal;
        self.captures.hover_pointer = self.pointer_cell;
        for t in self.terminals.iter_mut() {
            t.focus_gradient = gradient;
            t.set_palette(self.theme.ansi());
        }
        self.dress_host_accents();
    }

    /// Host accents: each pane's shell-reported OSC 7 host against the prefs
    /// rules (first match wins). Cleared the moment the host stops matching
    /// (an in-pane SSH session ends). Runs from `sync_focus_flags` AND at the
    /// top of `render`: the OSC 7 host arrives on a PTY reader thread with no
    /// input event behind it, so the PTY-dirty redraw is the only wakeup —
    /// dressing must not wait for the next key or click.
    fn dress_host_accents(&mut self) {
        for t in self.terminals.iter_mut() {
            let dress = t.shell_host().and_then(|h| {
                self.host_accents
                    .iter()
                    .find(|(m, _, _)| m.is_match(&h))
                    .map(|(_, c, b)| (*c, b.clone()))
            });
            match dress {
                Some((c, b)) => {
                    t.accent = Some(c);
                    t.accent_badge = b;
                }
                None => {
                    t.accent = None;
                    t.accent_badge = None;
                }
            }
        }
    }

    /// Whether popups/menus/tooltips should wear the orange→green gradient
    /// border and the muted dark-teal selection fill instead of the legacy
    /// bright-blue accent. Gated on the Black theme to mirror the focused-pane
    /// border, so Croft Dark keeps its coherent all-blue look.
    fn popup_gradient(&self) -> bool {
        self.theme.gradient()
    }

    /// Paint the bottom panel group's tab strip (PROBLEMS / TERMINAL) across
    /// `strip` (its top row) and record each tab's hit rect. The active tab is
    /// bright/bold; the inactive one is dim, mirroring VS Code's panel tabs. A
    /// non-zero problem count rides the PROBLEMS label as a badge.
    fn paint_panel_tabs(&mut self, frame: &mut ratatui::Frame, strip: Rect) {
        use ratatui::widgets::Block;
        let strip_bg = self.theme.editor_bg();
        frame.render_widget(Block::default().style(Style::default().bg(strip_bg)), strip);
        let brand = self.theme.gradient();
        let active_fg = if brand {
            crate::gradient::rgb_color(crate::gradient::PANEL_TITLE_FG)
        } else {
            Color::White
        };
        let inactive_fg = Color::Rgb(0x80, 0x88, 0x98);
        let right = strip.x + strip.width;
        let count = self.problems.total_count();
        let pointer = self.pointer_cell;
        let orange = crate::gradient::rgb_color(crate::gradient::GRAD_TR);
        let badge_fg = Color::Rgb(0x1a, 0x12, 0x0a);
        let active = self.bottom_panel_tab;

        self.problems_tab_rect = Rect::default();
        self.output_tab_rect = Rect::default();
        self.ports_tab_rect = Rect::default();
        self.captures_tab_rect = Rect::default();
        self.terminal_tab_rect = Rect::default();
        // In images mode the count rides as an orange circle (the same raster
        // badge as the activity bar), emitted post-frame; recompute its anchor
        // each paint. Glyph-fallback terminals keep the powerline-cap pill.
        let images = self.overlays.activity.has_images();
        self.problems_badge_cell = None;

        // VS Code panel-group order: PROBLEMS, OUTPUT, TERMINAL, PORTS. PROBLEMS
        // alone carries the orange count badge after its label.
        let tabs = [
            (BottomPanelTab::Problems, " PROBLEMS "),
            (BottomPanelTab::Output, " OUTPUT "),
            (BottomPanelTab::Terminal, " TERMINAL "),
            (BottomPanelTab::Ports, " PORTS "),
            (BottomPanelTab::Captures, " CAPTURES "),
        ];

        // Lay each tab out left to right, recording its hit rect (which, for
        // PROBLEMS, spans the label and the pill together).
        let mut placed: Vec<(BottomPanelTab, &str, Rect, u16)> = Vec::with_capacity(tabs.len());
        let mut x = strip.x + 1;
        for (tab, label) in tabs {
            if x >= right {
                break;
            }
            let badge_w = if tab == BottomPanelTab::Problems && count > 0 {
                if images {
                    crate::iterm2_inline::count_badge_cells_w(count)
                } else {
                    format!("{count}").chars().count() as u16 + 2
                }
            } else {
                0
            };
            let w = label.chars().count() as u16 + badge_w;
            let rect = Rect {
                x,
                y: strip.y,
                width: w.min(right.saturating_sub(x)),
                height: 1,
            };
            match tab {
                BottomPanelTab::Problems => self.problems_tab_rect = rect,
                BottomPanelTab::Output => self.output_tab_rect = rect,
                BottomPanelTab::Ports => self.ports_tab_rect = rect,
                BottomPanelTab::Captures => self.captures_tab_rect = rect,
                BottomPanelTab::Terminal => self.terminal_tab_rect = rect,
            }
            placed.push((tab, label, rect, badge_w));
            x = x.saturating_add(w + 1);
        }

        let buf = frame.buffer_mut();
        for (tab, label, rect, badge_w) in &placed {
            let is_active = *tab == active;
            // Active tab: brand fg + bold (and underlined below). Hover brightens
            // an inactive tab; the rest stay dim.
            let style = if is_active {
                Style::default()
                    .fg(active_fg)
                    .bg(strip_bg)
                    .add_modifier(Modifier::BOLD)
            } else if crate::widgets::hover::row_hover_bg(*rect, pointer, brand).is_some() {
                Style::default().fg(active_fg).bg(strip_bg)
            } else {
                Style::default().fg(inactive_fg).bg(strip_bg)
            };
            if rect.x < right {
                buf.set_stringn(
                    rect.x,
                    rect.y,
                    label,
                    right.saturating_sub(rect.x) as usize,
                    style,
                );
            }
            // Orange count badge after PROBLEMS. In images mode it's a raster
            // circle (matching the activity-bar badges) emitted post-frame, so
            // the cells stay blank strip_bg and we just record the anchor.
            // Otherwise the powerline-cap pill is drawn as text.
            if *badge_w > 0 {
                let bx = rect.x + label.chars().count() as u16;
                if images {
                    if bx < right {
                        self.problems_badge_cell = Some((bx, rect.y));
                    }
                } else {
                    let badge_text = format!("{count}");
                    let cap_style = Style::default().fg(orange).bg(strip_bg);
                    if bx < right {
                        buf.set_string(bx, rect.y, "\u{e0b6}", cap_style);
                    }
                    let inner_start = bx + 1;
                    if inner_start < right {
                        buf.set_stringn(
                            inner_start,
                            rect.y,
                            &badge_text,
                            right.saturating_sub(inner_start) as usize,
                            Style::default()
                                .fg(badge_fg)
                                .bg(orange)
                                .add_modifier(Modifier::BOLD),
                        );
                    }
                    let cap_r = inner_start + badge_text.chars().count() as u16;
                    if cap_r < right {
                        buf.set_string(cap_r, rect.y, "\u{e0b4}", cap_style);
                    }
                }
            }
            // The active-tab underline (VS Code's indicator) hugs the word only,
            // stopping before the padding spaces and the pill.
            if is_active {
                let leading = label.chars().take_while(|c| *c == ' ').count() as u16;
                let word_len = label.trim().chars().count() as u16;
                let start = rect.x + leading;
                for ux in start..(start + word_len).min(right) {
                    buf[(ux, rect.y)].modifier.insert(Modifier::UNDERLINED);
                }
            }
        }
    }

    /// Switch the bottom panel group's active tab, ensuring the panel is
    /// visible and the panel pane is focused so the new view is usable at once.
    fn set_bottom_panel_tab(&mut self, tab: BottomPanelTab) {
        self.bottom_panel_tab = tab;
        if !self.show_terminal {
            self.show_terminal = true;
        }
        self.focus_pane(Pane::Terminal);
    }

    /// Split the editor into two side-by-side columns (`Cmd+\`). The new
    /// group duplicates the active file (re-opens its path, copies the
    /// cursor/scroll position) and takes focus, landing in the right
    /// column. No-op if already split or the active tab has no path on
    /// disk (a blank/unsaved buffer has nothing to mirror).
    /// "Split Editor Right": split the active group side by side, the new
    /// focused duplicate to the right. The default split, on `Cmd+\`.
    fn split_editor(&mut self) {
        self.split_editor_dir(editor_layout::SplitDir::Horizontal, true);
    }

    /// Split the active group, duplicating its file into a new focused group
    /// placed in the direction the caller asks for. `dir` chooses the seam's
    /// orientation (Horizontal = side by side, Vertical = stacked) and
    /// `new_after` whether the NEW group sits after the existing one (right /
    /// below) or before it (left / above) — the four VS Code Split commands:
    /// Right = (H, after), Left = (H, before), Down = (V, after), Up = (V,
    /// before). Splitting is offered only from an unsplit editor for now.
    fn split_editor_dir(&mut self, dir: editor_layout::SplitDir, new_after: bool) {
        let Some(path) = self.editor.path.clone() else {
            self.status = String::from("Cannot split: save the file first");
            return;
        };
        // A fresh EditorTabs starts blank-initial; `open_preview` reuses
        // that placeholder tab so the new group holds exactly the file
        // (not a stray blank tab beside it). Opening it as the PREVIEW
        // slot - not pinned - means the next file the user opens in this
        // column swaps straight into it (clean "left = A, right = B"
        // comparison) rather than stacking a second tab. Editing or
        // double-clicking pins it, as everywhere else.
        let mut group = EditorTabs::default();
        if group.open_preview(&path).is_err() {
            self.status = String::from("Cannot split: failed to open file");
            return;
        }
        // Mirror the source view state (caret + scroll, incl. the wrap
        // sub-line offset) so the duplicate opens exactly where the
        // source was rather than at the top of the file.
        group.copy_view_position_from(&self.editor);
        // The new focused group (now in `self.editor`, always the active leaf)
        // takes the active slot; the existing group settles into the sibling.
        let existing = std::mem::replace(&mut self.editor, group);
        self.editor_layout.split_active(existing, dir, new_after);
        self.focus_pane(Pane::Editor);
    }

    /// VS Code "Move Editor into <dir> Group": relocate the active tab to the
    /// group adjacent in `dir`. If a neighbour exists there the tab moves into
    /// it (the source collapses when its last tab leaves); otherwise a new group
    /// is created in that direction holding the moved tab. Moving the only tab
    /// of a single group with no neighbour is a no-op (nowhere to move to).
    fn move_active_editor(&mut self, dir: editor_layout::Dir) {
        // A nominal area: seam adjacency is scale-invariant, so the exact pane
        // size doesn't matter for finding the directional neighbour.
        let synth = ratatui::layout::Rect::new(0, 0, 10_000, 10_000);
        match self.editor_layout.neighbor_leaf_in_dir(synth, 1, dir) {
            Some(target) => {
                let moved = self.editor.take_active_editor();
                let source_emptied = self.editor.is_blank_initial();
                let reduced = std::mem::take(&mut self.editor);
                self.editor = self.editor_layout.refocus_to_dfs(reduced, target);
                self.editor.push_editor(moved);
                if source_emptied {
                    self.editor_layout
                        .prune_blank_inactive(|t| t.is_blank_initial());
                }
                self.focus_pane(Pane::Editor);
            }
            None => {
                if self.editor.tab_count() <= 1 {
                    self.status = String::from("Move: the editor is already a single group");
                    return;
                }
                let moved = self.editor.take_active_editor();
                let mut group = EditorTabs::default();
                group.push_editor(moved);
                let existing = std::mem::replace(&mut self.editor, group);
                self.editor_layout
                    .split_active(existing, dir.split_dir(), dir.places_new_after());
                self.focus_pane(Pane::Editor);
            }
        }
    }

    /// VS Code "Split in Group": open a second view of the active file beside
    /// it. A TUI has no true in-group sub-view, so the observable equivalent is
    /// a side-by-side split duplicating the active file — the same result as
    /// Split Right.
    fn split_in_group(&mut self) {
        self.split_editor_dir(editor_layout::SplitDir::Horizontal, true);
    }

    /// Move keyboard focus to the editor group in the given physical
    /// column (`true` = left, `false` = right). Hoists the active group
    /// through `editor_layout` so the focused group is always `editor`, keeping
    /// the physical columns fixed. No-op when not split or already focused
    /// there.
    fn focus_editor_group(&mut self, want_left: bool) {
        if !self.editor_layout.is_split() {
            return;
        }
        // Physical columns map to depth-first leaf order: leftmost = 0,
        // rightmost = last. Hoist the active group out and pull the target
        // leaf's group into `self.editor` so the invariant holds.
        let target = if want_left {
            0
        } else {
            self.editor_layout.leaf_count() - 1
        };
        if self.editor_layout.active_dfs_index() == target {
            // Already focused there; the chord still doubles as "focus editor".
            if self.focus != Pane::Editor {
                self.focus_pane(Pane::Editor);
            }
            return;
        }
        let current = std::mem::take(&mut self.editor);
        self.editor = self.editor_layout.refocus_to_dfs(current, target);
        self.focus_pane(Pane::Editor);
    }

    /// The seam (if any) the cell `(col, row)` lands on, using the same
    /// two-cell hit-zone as the sidebar/terminal seams. Returns a clone so an
    /// in-flight drag can hold the boundary across frames.
    fn seam_at(&self, col: u16, row: u16) -> Option<editor_layout::Seam> {
        self.editor_seams
            .iter()
            .find(|s| match s.dir {
                editor_layout::SplitDir::Horizontal => {
                    (col == s.pos || col == s.pos.saturating_sub(1))
                        && row >= s.cross_start
                        && row < s.cross_end
                }
                editor_layout::SplitDir::Vertical => {
                    (row == s.pos || row == s.pos.saturating_sub(1))
                        && col >= s.cross_start
                        && col < s.cross_end
                }
            })
            .cloned()
    }

    /// After a tab close, collapse the split if the focused group ran out
    /// of real tabs. The surviving (other) group becomes the sole editor.
    fn collapse_split_if_empty(&mut self) {
        // While a full-screen window is open, `editor` is the window and the
        // grid is parked out of the tree — collapsing here would fold the
        // parked grid into the window. The window's own emptiness is handled by
        if !self.editor_layout.is_split() || !self.editor.is_blank_initial() {
            return;
        }
        // The focused group is empty; drop it and promote a surviving group to
        // become the new active editor. Evict the right slot's image so it
        // can't ghost after the column disappears.
        self.editor = self.editor_layout.collapse_active();
        self.editor_seams.clear();
        self.disable_editor_image(1);
        // Focus stays on the editor pane; just re-light the promoted
        // group's border. (No `focus_pane` so this is safe to call from
        // any close path without re-poking the cursor mid-frame.)
        self.sync_focus_flags();
    }

    /// VS Code "Move into New Window": open the tab at `idx` in a brand-new
    /// window of the host terminal (a real, separate window running croft on the
    /// same workspace with the file open), then close the tab here — the file
    /// has moved to the new window. The current window is otherwise untouched.
    fn move_into_new_window(&mut self, idx: usize) {
        if !self.open_tab_in_new_window(idx) {
            return;
        }
        // The file now lives in the new window; drop it from this one. Mirrors
        // MenuAction::CloseTab so the split collapses if this was its last tab.
        let label = self.editor.tab_display_label(idx);
        if self.editor.close_tab(idx) {
            self.sync_open_file_poll_mtime();
            self.poke_cursor();
            self.collapse_split_if_empty();
        }
        self.status = format!("{label}: moved into a new window");
    }

    /// VS Code "Copy into New Window" (⌘K O): open the tab at `idx` in a
    /// brand-new OS terminal window, leaving the original tab exactly where it
    /// is. The current window is not touched at all.
    fn copy_into_new_window(&mut self, idx: usize) {
        if !self.open_tab_in_new_window(idx) {
            return;
        }
        let label = self.editor.tab_display_label(idx);
        self.status = format!("{label}: copied into a new window");
    }

    /// Spawn a new OS terminal window running croft on the current workspace
    /// with the tab at `idx` opened. Returns false (and sets a status) when the
    /// action can't run: an unsaved/path-less buffer, a remote session (no
    /// local window server on the headless host), or a spawn failure. Shared by
    /// Move and Copy into New Window — the only difference is what the caller
    /// does to the source tab afterwards.
    fn open_tab_in_new_window(&mut self, idx: usize) -> bool {
        // A new croft process opens a file by path, so an untitled buffer has
        // nothing to hand off.
        let Some(path) = self.editor.tab_path(idx) else {
            self.status = String::from("New Window: save the file first");
            return false;
        };
        // A new OS window only exists where croft can talk to a window server:
        // the local machine. Over SSH croft runs on the headless host.
        if self.is_remote {
            self.status = String::from("New Window: not available over SSH");
            return false;
        }
        match spawn_new_window(&self.tree.root, &path) {
            Ok(()) => true,
            Err(e) => {
                self.status = format!("New Window failed: {e}");
                false
            }
        }
    }

    fn render(&mut self, frame: &mut ratatui::Frame) {
        let size = frame.area();
        self.last_frame_area = size;
        self.dress_host_accents();
        // Theme background, whole frame. croft's chrome (the sidebar panels,
        // explorer sections, activity bar, gaps) mostly paints `Color::Reset`
        // and leans on the iTerm2 `SetColors` session bg to color it. Ghostty /
        // Kitty / sixel ignore `SetColors`, so those Reset cells fall through to
        // the host terminal's own background (black), leaving only the surfaces
        // that fill an explicit bg (editor, terminal) themed. Prefilling the
        // frame with the theme bg colors every unfilled cell; widgets that set
        // their own bg override it (ratatui patches bg only when `Some`). Gated
        // to exactly the hosts where `SetColors` is NOT emitted (see
        // `apply_theme`): on iTerm2 the session bg already handles this and a
        // full-frame fill would force the OSC-1337 activity images to re-emit
        // every frame.
        if !crate::iterm2_inline::detect_iterm2_inline_support() {
            frame.render_widget(
                ratatui::widgets::Block::default()
                    .style(Style::default().bg(self.theme.editor_bg())),
                size,
            );
        }
        // The on-screen keyboard docks as a band between the panes and the
        // status bar, scaling its keys to thumb size on tall frames; frames
        // too short to host it keep it collapsed so the workspace can't be
        // squeezed into nothing.
        let osk_h = if self.osk.is_some() && size.height >= OSK_MIN_FRAME_HEIGHT {
            crate::widgets::osk::band_height(size.height)
        } else {
            0
        };
        // The bottom status bar can be hidden (Customize Layout / Zen Mode),
        // reclaiming its row for the workspace.
        let status_h: u16 = if self.status_bar_visible { 1 } else { 0 };
        let outer = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Min(1),
                Constraint::Length(osk_h),
                Constraint::Length(status_h),
            ])
            .split(size);
        let main_area = outer[0];

        // Reserve the activity bar (when shown) and the secondary side bar,
        // then clamp the primary side bar so the editor keeps RIGHT_PANE_MIN.
        let activity_w = if self.activity_bar_visible {
            ACTIVITY_BAR_WIDTH
        } else {
            0
        };
        let secondary_w = if self.secondary_side_bar_visible {
            SECONDARY_SIDEBAR_WIDTH
        } else {
            0
        };
        let max_sidebar = main_area
            .width
            .saturating_sub(activity_w)
            .saturating_sub(secondary_w)
            .saturating_sub(RIGHT_PANE_MIN);
        let sidebar_w = self
            .sidebar_width
            .clamp(SIDEBAR_WIDTH_MIN, max_sidebar.max(SIDEBAR_WIDTH_MIN));
        // Persist the clamped value so subsequent drags start from where
        // the user can actually see the splitter.
        self.sidebar_width = sidebar_w;

        // Panel Alignment = Justify spans the panel across the full content
        // width (under the side bar): carve it off the bottom of `main` BEFORE
        // the horizontal chrome split, so the side bars sit above it.
        let justify_panel = self.show_terminal
            && !self.terminal_maximized
            && osk_h == 0
            && self.panel_alignment == PanelAlignment::Justify;
        let (chrome_area, justify_terminal) = if justify_panel {
            let total_h = main_area.height;
            let max_h = total_h
                .saturating_sub(EDITOR_HEIGHT_MIN)
                .max(TERMINAL_HEIGHT_MIN);
            let term_h = self
                .terminal_height
                .unwrap_or(total_h / 3)
                .clamp(TERMINAL_HEIGHT_MIN, max_h);
            self.terminal_height = Some(term_h);
            let rows = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Min(EDITOR_HEIGHT_MIN),
                    Constraint::Length(term_h),
                ])
                .split(main_area);
            (rows[0], Some(rows[1]))
        } else {
            (main_area, None)
        };

        // Pure horizontal split of the workspace chrome (honors activity-bar
        // visibility, side bar position, and the secondary side bar).
        let chrome = compute_chrome_layout(
            chrome_area,
            self.activity_bar_visible,
            self.show_tree,
            self.secondary_side_bar_visible,
            self.side_bar_position,
            sidebar_w,
            SECONDARY_SIDEBAR_WIDTH,
        );
        let activity_area = chrome.activity;
        let side_area = chrome.primary_side;
        let secondary_area = chrome.secondary_side;
        let right_area = chrome.right;
        // Remember the Explorer column so the zoxide jump popup can anchor
        // over it instead of centering on the whole frame.
        self.last_sidebar_area = side_area;
        self.sidebar_splitter_x = chrome.sidebar_splitter_x;
        self.last_content_width = right_area.width;
        self.last_content_height = right_area.height;

        // Editor ↔ terminal split within the editor column. `terminal_band` is
        // the full bottom strip; `terminal_area` is where the terminals draw
        // (narrower than the band under Left/Right alignment).
        let (editor_area, terminal_area, terminal_band) = if let Some(jt) = justify_terminal {
            // The panel was already carved full-width from `main`; the editor
            // fills the rest of its column and the splitter sits at the seam.
            self.terminal_splitter_y = Some(jt.y);
            (right_area, Some(jt), Some(jt))
        } else if osk_h > 0 && self.focus == Pane::Terminal && self.show_terminal {
            let zero_editor = Rect {
                x: right_area.x,
                y: right_area.y,
                width: right_area.width,
                height: 0,
            };
            self.terminal_splitter_y = None;
            (zero_editor, Some(right_area), Some(right_area))
        } else if osk_h > 0 {
            self.terminal_splitter_y = None;
            (right_area, None, None)
        } else if self.show_terminal {
            if self.terminal_maximized {
                // Editor / welcome collapses; terminal fills the entire
                // right column next to the Explorer. Splitter is hidden
                // because there is nothing to drag against.
                let zero_editor = Rect {
                    x: right_area.x,
                    y: right_area.y,
                    width: right_area.width,
                    height: 0,
                };
                self.terminal_splitter_y = None;
                (zero_editor, Some(right_area), Some(right_area))
            } else {
                let total_h = right_area.height;
                let pinned = self.terminal_height.map(|h| {
                    h.clamp(
                        TERMINAL_HEIGHT_MIN,
                        total_h
                            .saturating_sub(EDITOR_HEIGHT_MIN)
                            .max(TERMINAL_HEIGHT_MIN),
                    )
                });
                let rows = if let Some(term_h) = pinned {
                    self.terminal_height = Some(term_h);
                    Layout::default()
                        .direction(Direction::Vertical)
                        .constraints([
                            Constraint::Min(EDITOR_HEIGHT_MIN),
                            Constraint::Length(term_h),
                        ])
                        .split(right_area)
                } else {
                    Layout::default()
                        .direction(Direction::Vertical)
                        .constraints([Constraint::Percentage(65), Constraint::Percentage(35)])
                        .split(right_area)
                };
                self.terminal_splitter_y = Some(rows[1].y);
                let band = rows[1];
                // Left/Right alignment hugs the panel to that half of the band.
                let term = panel_band_rect(band, self.panel_alignment);
                (rows[0], Some(term), Some(band))
            }
        } else {
            self.terminal_splitter_y = None;
            (right_area, None, None)
        };

        if let Some(activity_area) = activity_area {
            self.render_activity_bar(frame, activity_area);
        } else {
            // Hidden activity bar: zero the icon hit-rects so clicks and the
            // post-draw OSC image flush both treat it as absent (no ghosting).
            self.sidebar_areas = SidebarAreas::default();
        }

        // Secondary side bar: the active file's Outline, on the edge opposite
        // the primary side bar.
        self.render_secondary_side_bar(frame, secondary_area);

        if let Some(area) = side_area {
            let usable_area = area;
            // Feed the render-time pointer cell to every side panel so the row
            // under the cursor (and the remote header pills) can light up,
            // mirroring the editor tab strip and terminal pane buttons.
            let panel_pointer = self.pointer_cell;
            self.tree.hover_pointer = panel_pointer;
            self.search.hover_pointer = panel_pointer;
            self.source_control.hover_pointer = panel_pointer;
            self.remote.hover_pointer = panel_pointer;
            self.outline.hover_pointer = panel_pointer;
            self.open_editors.hover_pointer = panel_pointer;
            self.timeline.hover_pointer = panel_pointer;
            self.dependencies.hover_pointer = panel_pointer;
            self.extensions.hover_pointer = panel_pointer;
            self.commit_graph.hover_pointer = panel_pointer;
            // Explorer stacks its toggled sub-views (Open Editors / Folders /
            // Outline / Timeline / Dependencies) inside the usable strip.
            // Every other sidebar view fills it with its single activity widget.
            match self.sidebar_view {
                SidebarView::Explorer => self.render_explorer_sections(frame, usable_area),
                SidebarView::Search => frame.render_widget(&mut self.search, usable_area),
                SidebarView::SourceControl => {
                    // The COMMITS graph section docks under the change list,
                    // capped at half the strip (like the Explorer sub-views).
                    // Hidden entirely while the repo empty-state hero shows.
                    let graph_h = if self.source_control.status.in_repo {
                        self.commit_graph
                            .desired_height(usable_area.height)
                            .min(usable_area.height.saturating_sub(6))
                    } else {
                        0
                    };
                    let scm_area = Rect {
                        height: usable_area.height - graph_h,
                        ..usable_area
                    };
                    frame.render_widget(&mut self.source_control, scm_area);
                    if graph_h > 0 {
                        let graph_area = Rect {
                            y: usable_area.y + usable_area.height - graph_h,
                            height: graph_h,
                            ..usable_area
                        };
                        frame.render_widget(&mut self.commit_graph, graph_area);
                    } else {
                        self.commit_graph.last_area = Rect::default();
                    }
                }
                SidebarView::Remote => frame.render_widget(&mut self.remote, usable_area),
                SidebarView::RunDebug => frame.render_widget(&mut self.run_debug, usable_area),
                SidebarView::Extensions => frame.render_widget(&mut self.extensions, usable_area),
                SidebarView::Testing => frame.render_widget(&mut self.testing, usable_area),
            }
        }
        if !self.editor_layout.is_split() && self.editor.is_blank_initial() {
            self.render_welcome(frame, editor_area);
            // The previous frame may have rendered an image-preview tab
            // whose OSC-1337 pixels are still cached in iTerm's image
            // store. Closing that tab brings us here, but ratatui's diff
            // alone doesn't tell iTerm to drop the image — flag it so the
            // main loop wipes the screen on the next pass. Both slots, in
            // case a split was just collapsed back to the welcome screen.
            self.disable_editor_image(0);
            self.disable_editor_image(1);
            // The welcome screen has no minimap (no document to preview).
            self.disable_minimap_image();
            self.editor_seams.clear();
            // Keep the editor's hit-test rectangles fresh so the activity-bar
            // / tree click logic still works even though we skipped the
            // EditorTabs widget this frame.
            self.editor.last_full_area = editor_area;
            self.editor.last_area = Rect {
                x: editor_area.x,
                y: editor_area.y,
                width: editor_area.width,
                height: 0,
            };
        } else {
            // The editor just overdrew whatever cells the welcome image
            // occupied; if the user reopens the welcome screen we'll need
            // to re-emit it.
            self.overlays.welcome.mark_dirty();
            // Feed the render-time pointer cell to every editor group so the
            // tab strip can light the hovered tab body / close-cross pill,
            // mirroring the terminal pane buttons' hover affordance.
            let pointer = self.pointer_cell;
            self.editor.hover_pointer = pointer;
            // Breadcrumb bar: recompute the path + symbol trail for the active
            // file each frame so it tracks caret moves and outline updates.
            self.editor.breadcrumbs = self.build_breadcrumbs();
            // Sticky scroll: recompute the pinned scope headers from the top
            // visible line each frame so they track scrolling.
            self.editor.sticky_lines = self.build_sticky_lines();
            // Multiplayer ghost carets: other participants' parked carets in
            // the active file, in their colors. The current typist's caret is
            // the live cursor, so it never ghosts; departed participants drop
            // out with the roster.
            self.editor.ghost_carets = match self.editor.path.clone() {
                Some(path) if !self.session_carets.is_empty() => self
                    .session_carets
                    .iter()
                    .filter(|(id, parked)| {
                        Some(**id) != self.session_typist
                            && parked.path == path
                            && self.session_participants.iter().any(|p| p.id == **id)
                    })
                    .map(|(id, parked)| (parked.row, parked.col, participant_color(*id)))
                    .collect(),
                _ => Vec::new(),
            };
            // Collab peers' carets (Phase D independent viewports): same
            // ghost rendering, keyed by workspace-relative file, plus a name
            // tag while the caret is inside its fade window. The seated
            // navigator's caret wears its identity accent.
            self.editor.ghost_caret_labels.clear();
            if !self.collab_carets.is_empty()
                && let Some(active) = self
                    .editor
                    .path
                    .as_ref()
                    .and_then(|p| collab_file_key(&self.tree.root, p))
            {
                let navigator_sites = self
                    .pair_host
                    .as_ref()
                    .map(|h| h.caret_sites())
                    .unwrap_or_default();
                let now = std::time::Instant::now();
                for (site, c) in &self.collab_carets {
                    if c.file != active {
                        continue;
                    }
                    let color = collab_caret_color(&navigator_sites, *site);
                    self.editor.ghost_carets.push((c.row, c.col, color));
                    if !c.name.is_empty() && now.duration_since(c.last_moved) < CARET_LABEL_FADE {
                        self.editor
                            .ghost_caret_labels
                            .push((c.row, c.col, c.name.clone(), color));
                    }
                }
            }
            // Gutter stop button for an AI stream into the active file; the
            // hoisted group is the only one that shows it (clear the rest so
            // a group swap never leaves a stale button behind).
            self.editor.stream_stop_line = self.stream_stop_row();
            // The navigator's comment boxes for the active file, same
            // hoisting rule (rows come from poll_pair's per-tick snapshot).
            let author = self
                .pair_host
                .as_ref()
                .map(|h| h.name().to_string())
                .unwrap_or_default();
            self.editor.comment_boxes = self
                .editor
                .path
                .as_ref()
                .and_then(|p| collab_file_key(&self.tree.root, p))
                .and_then(|file| self.navigator_notes.get(&file))
                .map(|notes| {
                    notes
                        .iter()
                        .map(|(id, row, body)| crate::widgets::editor::CommentBox {
                            id: *id,
                            line: *row,
                            author: author.clone(),
                            body: body.clone(),
                        })
                        .collect()
                })
                .unwrap_or_default();
            // A focused box that vanished (ignored elsewhere, cleared, or
            // re-anchored away) releases the keyboard back to the buffer.
            if let Some(focus) = &self.editor.comment_focus
                && !self.editor.comment_boxes.iter().any(|b| b.id == focus.id)
            {
                self.editor.comment_focus = None;
            }
            for group in self.editor_layout.inactive_groups_mut() {
                for ed in &mut group.editors {
                    ed.stream_stop_line = None;
                    ed.comment_boxes.clear();
                    ed.comment_focus = None;
                }
            }
            // Render the editor group layout tree. The active group is hoisted
            // into `self.editor`; every other group lives in `editor_layout`.
            // Lay the leaves out and paint each at its rect (depth-first order),
            // reporting the active group's rect so popups anchor there.
            let rects = self.editor_layout.leaf_rects(editor_area, EDITOR_SPLIT_MIN);
            let active_idx = self.editor_layout.active_dfs_index();
            let focused_area = if self.editor_layout.is_split() {
                let active_area = rects[active_idx];
                frame.render_widget(&mut self.editor, active_area);
                let inactive_rects: Vec<Rect> = rects
                    .iter()
                    .enumerate()
                    .filter(|(i, _)| *i != active_idx)
                    .map(|(_, r)| *r)
                    .collect();
                for (group, rect) in self
                    .editor_layout
                    .inactive_groups_mut()
                    .into_iter()
                    .zip(inactive_rects)
                {
                    group.hover_pointer = pointer;
                    frame.render_widget(group, rect);
                }
                // Every boundary in the grid is a draggable seam (one per
                // internal child edge of every split node, any depth).
                self.editor_seams = self.editor_layout.seams(editor_area, EDITOR_SPLIT_MIN);
                // Image overlays stay keyed by physical column (0 = left).
                if rects.len() == 2 {
                    self.update_editor_image_overlay(0, rects[0]);
                    self.update_editor_image_overlay(1, rects[1]);
                } else {
                    self.update_editor_image_overlay(0, active_area);
                    self.disable_editor_image(1);
                }
                // ponytail: no minimap while the editor is split; per-group
                // minimaps when someone asks for them.
                self.disable_minimap_image();
                active_area
            } else if let Some((ed_rect, full_strip, img_rect)) = self.carve_minimap(editor_area) {
                // Bg-fill the whole strip column so no stale cells show
                // through, then paint the editor into the narrowed rect and
                // bake the minimap raster into the text-aligned sub-rect.
                frame.render_widget(
                    ratatui::widgets::Block::default()
                        .style(Style::default().bg(self.theme.editor_bg())),
                    full_strip,
                );
                frame.render_widget(&mut self.editor, ed_rect);
                self.editor_seams.clear();
                self.update_editor_image_overlay(0, ed_rect);
                self.disable_editor_image(1);
                self.update_minimap_overlay(img_rect);
                ed_rect
            } else {
                frame.render_widget(&mut self.editor, editor_area);
                self.editor_seams.clear();
                self.update_editor_image_overlay(0, editor_area);
                // No right pane: make sure its slot can't ghost an image.
                self.disable_editor_image(1);
                self.disable_minimap_image();
                editor_area
            };
            let grad = self.popup_gradient();
            if self.focus == Pane::Editor
                && self.completion_popup.is_some()
                && let Some((cx, cy)) = self.editor.cursor_screen_pos()
            {
                if let Some(popup) = self.completion_popup.as_mut() {
                    popup.anchor = (cx, cy);
                    popup.gradient = grad;
                }
                let popup_ref = self.completion_popup.as_ref().unwrap();
                let area = popup_ref.area_for(focused_area);
                if area.width > 0 && area.height > 0 {
                    frame.render_widget(popup_ref, area);
                }
            }
            // Parameter hints sit ABOVE the caret, so they coexist with the
            // completion popup below it.
            if self.focus == Pane::Editor
                && self.signature_help_popup.is_some()
                && let Some((cx, cy)) = self.editor.cursor_screen_pos()
            {
                if let Some(popup) = self.signature_help_popup.as_mut() {
                    popup.anchor = (cx, cy);
                    popup.gradient = grad;
                }
                let popup_ref = self.signature_help_popup.as_ref().unwrap();
                let area = popup_ref.area_for(focused_area);
                if area.width > 0 && area.height > 0 {
                    frame.render_widget(popup_ref, area);
                }
            }
            if let Some(popup) = self.tab_tooltip.as_mut() {
                popup.gradient = grad;
                let area = popup.area_for(focused_area);
                if area.width > 0 && area.height > 0 {
                    frame.render_widget(&*popup, area);
                }
            }
            // Layout-control icons at the top-right of the editor tab strip.
            let strip_row = Rect {
                x: editor_area.x,
                y: editor_area.y,
                width: editor_area.width,
                height: 1,
            };
            self.paint_layout_icons(frame, strip_row);
        }
        if let Some(area) = terminal_area {
            // Left/Right panel alignment narrows the terminal to one half of
            // its band; paint the leftover strip with the editor background so
            // the vacated cells don't ghost the previous frame.
            if let Some(band) = terminal_band
                && (band.width != area.width || band.x != area.x)
            {
                frame.render_widget(
                    ratatui::widgets::Block::default()
                        .style(Style::default().bg(self.theme.editor_bg())),
                    band,
                );
            }
            // The panel group's tab strip (PROBLEMS / TERMINAL) takes the top
            // row; the active tab's view fills the rest. Mirrors VS Code's
            // bottom-panel tab bar.
            let strip = Rect {
                x: area.x,
                y: area.y,
                width: area.width,
                height: 1,
            };
            let content = if area.height > 1 {
                Rect {
                    x: area.x,
                    y: area.y + 1,
                    width: area.width,
                    height: area.height - 1,
                }
            } else {
                area
            };
            self.paint_panel_tabs(frame, strip);
            match self.bottom_panel_tab {
                BottomPanelTab::Terminal => {
                    let n = self.terminals.len().max(1);
                    let multi = self.terminals.len() > 1;
                    let maximized = self.terminal_pane_maximized && multi;
                    self.clear_terminal_rail();
                    // Maximize mode: the active pane owns the panel's width
                    // minus a right rail listing every terminal (VS Code's
                    // terminal-tabs list); hidden panes drop their hit rects
                    // so clicks can't phantom-match. Otherwise: even split.
                    let cols: Vec<Rect> = if maximized {
                        // The rail is a fixed, very narrow switcher column:
                        // icon + 4 label characters, nothing adaptive.
                        let rail_w = TERMINAL_RAIL_W.min(content.width.saturating_sub(20));
                        let pane = Rect {
                            x: content.x,
                            y: content.y,
                            width: content.width - rail_w,
                            height: content.height,
                        };
                        let rail = Rect {
                            x: content.x + pane.width,
                            y: content.y,
                            width: rail_w,
                            height: content.height,
                        };
                        self.paint_terminal_rail(frame, rail);
                        (0..n)
                            .map(|i| {
                                if i == self.active_terminal {
                                    pane
                                } else {
                                    Rect::default()
                                }
                            })
                            .collect()
                    } else {
                        let constraints: Vec<Constraint> =
                            (0..n).map(|_| Constraint::Ratio(1, n as u32)).collect();
                        Layout::default()
                            .direction(Direction::Horizontal)
                            .constraints(constraints)
                            .split(content)
                            .to_vec()
                    };
                    // Theme the terminal background like VS Code's integrated
                    // terminal: prefill each pane with the theme bg before the
                    // grid paints. Shell-colored cells override it; default-bg
                    // cells (Style bg = None) keep the fill. On iTerm2 this
                    // matches the SetColors session bg; on Ghostty/Kitty (which
                    // ignores SetColors) it's what makes the terminal follow the
                    // theme at all instead of showing the host's own bg.
                    let term_bg = self.theme.editor_bg();
                    for (i, t) in self.terminals.iter_mut().enumerate() {
                        if cols[i].width == 0 {
                            t.last_area = Rect::default();
                        } else {
                            frame.render_widget(
                                ratatui::widgets::Block::default()
                                    .style(Style::default().bg(term_bg)),
                                cols[i],
                            );
                            frame.render_widget(t, cols[i]);
                        }
                    }
                    let show_close = multi;
                    let brand = self.theme.gradient();
                    self.terminal_add_buttons.clear();
                    self.terminal_profile_buttons.clear();
                    self.terminal_close_buttons.clear();
                    self.terminal_max_buttons.clear();
                    self.terminal_label_rects.clear();
                    for (i, col) in cols.iter().enumerate().take(self.terminals.len()) {
                        // Hidden panes still push placeholders so a button's
                        // position in each vec names its terminal index.
                        if col.width == 0 {
                            self.terminal_add_buttons.push(Rect::default());
                            self.terminal_profile_buttons.push(Rect::default());
                            self.terminal_close_buttons.push(Rect::default());
                            self.terminal_max_buttons.push(Rect::default());
                            self.terminal_label_rects.push(Rect::default());
                            continue;
                        }
                        let buttons = paint_terminal_pane_buttons(
                            frame,
                            *col,
                            show_close,
                            maximized,
                            brand,
                            self.pointer_cell,
                        );
                        self.terminal_add_buttons
                            .push(buttons.add.unwrap_or_default());
                        self.terminal_profile_buttons
                            .push(buttons.profile.unwrap_or_default());
                        self.terminal_close_buttons
                            .push(buttons.close.unwrap_or_default());
                        self.terminal_max_buttons
                            .push(buttons.max.unwrap_or_default());
                        // Auto/manual pane label at top-left, only with 2+ panes
                        // (a lone pane needs no name). Kept clear of the buttons.
                        // The painted pill doubles as the drag-reorder handle,
                        // so its rect is recorded index-aligned with the pane.
                        let mut label_rect = Rect::default();
                        if multi {
                            let label = self.terminals[i].label().to_string();
                            // The pill is painted AFTER the header buttons and
                            // wins the shared cells, so its budget has to
                            // clear the button strip plus the pill's own
                            // widest decoration (a leading `⚠` or `⇶` and the
                            // two spaces every pill carries).
                            let room =
                                col.width.saturating_sub(TERMINAL_BUTTON_STRIP_W + 4) as usize;
                            // While broadcast input is on, every pane that
                            // receives the mirrored keystrokes wears an
                            // unmissable red pill with a ⇶ marker
                            // (Terminator's role colouring); excluded panes
                            // keep the normal pill. The marker paints even
                            // while the pane's auto-label is still empty.
                            let receiving = self.broadcast_input
                                && (i == self.active_terminal
                                    || !self.terminals[i].broadcast_excluded);
                            if (!label.is_empty() || receiving) && room >= 3 {
                                let shown: String = label.chars().take(room).collect();
                                let mut text = if receiving && shown.is_empty() {
                                    String::from(" \u{21f6} ")
                                } else if receiving {
                                    format!(" \u{21f6} {shown} ")
                                } else {
                                    format!(" {shown} ")
                                };
                                // A live OSC 9;4 percent joins the pill (the
                                // border gauge is the primary drawing; this
                                // keeps unfocused panes glanceable). The
                                // indeterminate state has no number to show.
                                if let Some((state, pct)) = self.terminals[i].progress()
                                    && state != 3
                                    && text.chars().count() + 6 <= room
                                {
                                    text = format!("{}\u{b7} {pct}% ", text);
                                }
                                let accent = self.terminals[i].accent;
                                let text = if accent.is_some() && !receiving {
                                    format!(" \u{26a0}{text}")
                                } else {
                                    text
                                };
                                let style = if receiving {
                                    Style::default()
                                        .fg(Color::Black)
                                        .bg(Color::Rgb(0xe7, 0x70, 0x70))
                                        .add_modifier(Modifier::BOLD)
                                } else if let Some((r, g, b)) = accent {
                                    Style::default()
                                        .fg(Color::Black)
                                        .bg(Color::Rgb(r, g, b))
                                        .add_modifier(Modifier::BOLD)
                                } else {
                                    crate::widgets::header_pill::action_style(brand, false)
                                };
                                // `room` bounds how much of the name is worth
                                // showing, but it counts CHARACTERS while the
                                // buffer advances by display CELLS, so a CJK
                                // or emoji name is twice as wide as its budget
                                // and would still reach the buttons. Clip the
                                // paint to the cells before the button strip —
                                // `set_stringn` measures grapheme width, which
                                // is the same clamp the rail rows use — and
                                // take the drag handle's width from what was
                                // actually painted.
                                let budget =
                                    col.width.saturating_sub(TERMINAL_BUTTON_STRIP_W) as usize;
                                let (end_x, _) = frame
                                    .buffer_mut()
                                    .set_stringn(col.x, col.y, text, budget, style);
                                label_rect = Rect {
                                    x: col.x,
                                    y: col.y,
                                    width: end_x.saturating_sub(col.x),
                                    height: 1,
                                };
                            }
                        }
                        self.terminal_label_rects.push(label_rect);
                    }
                }
                BottomPanelTab::Problems => {
                    // The terminals are hidden behind the PROBLEMS view; drop
                    // their hit rects so a click never phantom-matches a pane
                    // that isn't painted (mirrors the hidden-panel reset).
                    self.terminal_add_buttons.clear();
                    self.terminal_profile_buttons.clear();
                    self.terminal_close_buttons.clear();
                    self.terminal_max_buttons.clear();
                    self.terminal_label_rects.clear();
                    self.clear_terminal_rail();
                    for t in self.terminals.iter_mut() {
                        t.last_area = Rect::default();
                    }
                    frame.render_widget(&mut self.problems, content);
                }
                BottomPanelTab::Output => {
                    // Same hidden-terminal reset as PROBLEMS: the OUTPUT view
                    // covers the panes, so their hit rects must not linger.
                    self.terminal_add_buttons.clear();
                    self.terminal_profile_buttons.clear();
                    self.terminal_close_buttons.clear();
                    self.terminal_max_buttons.clear();
                    self.terminal_label_rects.clear();
                    self.clear_terminal_rail();
                    for t in self.terminals.iter_mut() {
                        t.last_area = Rect::default();
                    }
                    frame.render_widget(&mut self.output, content);
                }
                BottomPanelTab::Ports => {
                    // Same hidden-terminal reset: the PORTS view covers the
                    // panes, so their hit rects must not linger.
                    self.terminal_add_buttons.clear();
                    self.terminal_profile_buttons.clear();
                    self.terminal_close_buttons.clear();
                    self.terminal_max_buttons.clear();
                    self.terminal_label_rects.clear();
                    self.clear_terminal_rail();
                    for t in self.terminals.iter_mut() {
                        t.last_area = Rect::default();
                    }
                    frame.render_widget(&mut self.ports, content);
                }
                BottomPanelTab::Captures => {
                    // Same hidden-terminal reset as the PORTS arm above.
                    self.terminal_add_buttons.clear();
                    self.terminal_profile_buttons.clear();
                    self.terminal_close_buttons.clear();
                    self.terminal_max_buttons.clear();
                    self.terminal_label_rects.clear();
                    self.clear_terminal_rail();
                    for t in self.terminals.iter_mut() {
                        t.last_area = Rect::default();
                    }
                    frame.render_widget(&mut self.captures, content);
                }
            }
        } else {
            self.terminal_add_buttons.clear();
            self.terminal_profile_buttons.clear();
            self.terminal_close_buttons.clear();
            self.terminal_max_buttons.clear();
            self.terminal_label_rects.clear();
            self.clear_terminal_rail();
            self.problems_tab_rect = Rect::default();
            self.output_tab_rect = Rect::default();
            self.ports_tab_rect = Rect::default();
            self.captures_tab_rect = Rect::default();
            self.terminal_tab_rect = Rect::default();
            // A hidden terminal must not keep stale hit rects alive, or
            // `terminal_at_pos` would phantom-match clicks meant for
            // whatever now occupies those cells (mirrors the SYSTEM
            // panel's hidden-state reset).
            for t in self.terminals.iter_mut() {
                t.last_area = Rect::default();
            }
        }

        let mut spans: Vec<Span> = Vec::with_capacity(20);
        spans.extend(brand_spans());
        if let Some(span) = self.perf.status_span() {
            spans.push(span);
        }
        if self.update_status == UpdateStatus::Ready {
            spans.push(Span::styled(
                " ⟳ Update ready - F9 to relaunch ",
                Style::default()
                    .bg(Color::Rgb(0x1f, 0x7a, 0x33))
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
            ));
        }
        if self.update_status == UpdateStatus::InProgress {
            // Red + a spinning circular-arrow glyph to draw the eye to the
            // in-progress background update.
            spans.push(Span::styled(
                format!(
                    " {} Updating croft in the background ",
                    self.update_spinner_glyph()
                ),
                Style::default()
                    .fg(Color::Rgb(0xff, 0x45, 0x4d))
                    .add_modifier(Modifier::BOLD),
            ));
        }
        if let Some(progress) = self.lsp_progress_status() {
            // A busy language server (rust-analyzer priming its crate graph,
            // etc.) is otherwise invisible: hover/completion just return empty
            // until it finishes. Surfacing "rust-analyzer: Indexing " tells
            // the user to wait rather than assume the server is dead.
            spans.push(Span::styled(
                format!(" ⟳ {progress} "),
                Style::default()
                    .fg(Color::Rgb(0x4e, 0x9a, 0xff))
                    .add_modifier(Modifier::BOLD),
            ));
        }
        if let Some(label) = &self.mcp_busy_label {
            // An in-flight extension command (install + tool call on a worker
            // thread) is otherwise invisible; an animated badge says it's working.
            spans.push(Span::styled(
                format!(" {} {label} ", self.mcp_spinner_glyph()),
                Style::default()
                    .fg(Color::Rgb(0x2d, 0xd4, 0xbf))
                    .add_modifier(Modifier::BOLD),
            ));
        }
        if self.vim.enabled {
            let (text, bg) = match self.vim.command_line() {
                Some(cmd) => (format!(" {cmd} "), Color::Rgb(0x33, 0x33, 0x33)),
                None => {
                    let label = self.vim.mode_label().unwrap_or("NORMAL");
                    let bg = match self.vim.mode() {
                        crate::vim::VimMode::Insert => Color::Rgb(0x1f, 0x7a, 0x33),
                        crate::vim::VimMode::Visual | crate::vim::VimMode::VisualLine => {
                            Color::Rgb(0x8a, 0x4f, 0xbf)
                        }
                        _ => Color::Rgb(0x4e, 0x9a, 0xff),
                    };
                    (format!(" {label} "), bg)
                }
            };
            spans.push(Span::styled(
                text,
                Style::default()
                    .bg(bg)
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw(" "));
        }
        spans.extend(git_status_spans(self.git.status()));
        spans.push(Span::raw("  "));
        // Persistent orange badge for a remote session with no dtach: it can't
        // survive a transport drop, so flag it for the whole session (rendered
        // before the transient status so a status update never hides it).
        if let Some(warning) = self.persistence_warning {
            spans.push(Span::styled(
                format!(" \u{26a0} {warning} "),
                Style::default()
                    .bg(Color::Rgb(0xff, 0x9d, 0x2f))
                    .fg(Color::Rgb(0x10, 0x13, 0x1a))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw("  "));
        }
        // Multiplayer roster badge: how many clients are attached to this
        // persistent session, painted only when someone else is here
        // (manage them via Session: Participants, Cmd+K A).
        if self.session_participants.len() > 1 {
            spans.push(Span::styled(
                format!(" \u{f0c0} {} attached ", self.session_participants.len()),
                Style::default()
                    .bg(Color::Rgb(0x2f, 0x6f, 0xd0))
                    .fg(Color::Rgb(0xff, 0xff, 0xff))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw("  "));
        }
        // AI-stream badge: a pilot is streaming an edit into a shared file;
        // orange like the persistence warning (attention, not decoration),
        // naming the cancel chord so the stop path is one glance away.
        if let Some(stream) = &self.collab_stream {
            spans.push(Span::styled(
                format!(
                    " \u{23f9} {} streaming into {} (Cmd+K X to stop) ",
                    stream.name, stream.file
                ),
                Style::default()
                    .bg(Color::Rgb(0xff, 0x9d, 0x2f))
                    .fg(Color::Rgb(0x10, 0x13, 0x1a))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw("  "));
        } else if let Some(host) = &self.pair_host {
            // Resident navigator seated and idle: presence, not attention —
            // the stream badge above takes over whenever it is typing.
            spans.push(Span::styled(
                format!(" \u{25c6} {} seated ", host.title()),
                Style::default()
                    .bg(Color::Rgb(0x3c, 0x41, 0x4f))
                    .fg(Color::Rgb(0xff, 0x9d, 0x2f))
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw("  "));
        }
        // Diagnostics counts (click → PROBLEMS), VS Code-style, after git.
        // Always shown so the bar reads as a health indicator at a glance.
        let err_count = self.problems.error_count();
        let warn_count = self.problems.warning_count();
        let diag_start_col: u16 = spans.iter().map(|s| s.content.chars().count() as u16).sum();
        let diag_text = format!(" \u{ea87} {err_count}  \u{ea6c} {warn_count} ");
        let diag_len = diag_text.chars().count() as u16;
        spans.push(Span::styled(
            format!(" \u{ea87} {err_count} "),
            Style::default().fg(Color::Rgb(0xf1, 0x4c, 0x4c)),
        ));
        spans.push(Span::styled(
            format!(" \u{ea6c} {warn_count} "),
            Style::default().fg(Color::Rgb(0xcc, 0xa7, 0x00)),
        ));
        // Transient status message (e.g. "Saved editor.rs"), no keybinding
        // cheat-sheet — those live in F1 / the Command Palette now.
        if !self.status.is_empty() {
            spans.push(Span::raw("  "));
            spans.push(Span::raw(self.status.clone()));
        }

        if let Some(osk) = self.osk.as_mut() {
            if osk_h > 0 {
                crate::widgets::osk::render_osk(osk, outer[1], frame.buffer_mut(), self.theme);
            } else {
                // Collapsed (frame too short): zero the hit rect so the
                // invisible band can't swallow clicks.
                osk.last_area = Rect::default();
            }
        }

        let status_rect = outer[2];
        // The F1 cheat-sheet is gone; F1 / the palette still open Shortcuts.
        self.shortcuts_hit_rect = None;
        // Diagnostics hit rect (left group), for click-to-PROBLEMS.
        self.status_diag_rect = if status_h > 0 {
            Rect {
                x: status_rect.x.saturating_add(diag_start_col),
                y: status_rect.y,
                width: diag_len.min(status_rect.width.saturating_sub(diag_start_col)),
                height: 1,
            }
        } else {
            Rect::default()
        };

        // ---- Right cluster: document facts, right-justified. Indentation /
        // encoding / EOL / language are clickable to change (hit rects recorded
        // below). ----
        let dim = Style::default().fg(Color::Rgb(0x9a, 0xa4, 0xb8));
        let right: Vec<Span> = vec![
            Span::styled(
                format!(
                    " Ln {}, Col {} ",
                    self.editor.cursor_row + 1,
                    self.editor.cursor_col + 1
                ),
                dim,
            ),
            Span::styled(format!(" {} ", self.editor.indent_style().label()), dim),
            Span::styled(format!(" {} ", self.editor.encoding.name()), dim),
            Span::styled(format!(" {} ", self.editor.eol.label()), dim),
            Span::styled(format!(" {} ", self.editor.language_label()), dim),
        ];
        let widths: Vec<u16> = right
            .iter()
            .map(|s| s.content.chars().count() as u16)
            .collect();
        let right_total: u16 = widths.iter().sum();

        // Black theme: drop the navy status strip to a near-black seam (a hair
        // lighter than the #000000 editor so the bar still reads as distinct),
        // matching VS Code's OLED themes. Croft Dark keeps the navy band.
        let status_bg = if self.popup_gradient() {
            Color::Rgb(0x18, 0x18, 0x18)
        } else {
            Color::Rgb(0x1e, 0x3a, 0x6e)
        };
        // Left fills the whole bar (background + left text); the right cluster
        // overwrites the right portion.
        frame.render_widget(
            Paragraph::new(Line::from(spans)).style(Style::default().bg(status_bg)),
            status_rect,
        );
        // Reset clickable rects; re-record only when the right cluster fits.
        self.status_indent_rect = Rect::default();
        self.status_encoding_rect = Rect::default();
        self.status_eol_rect = Rect::default();
        self.status_language_rect = Rect::default();
        if status_h > 0 && right_total > 0 && right_total <= status_rect.width {
            let rx = status_rect.right() - right_total;
            frame.render_widget(
                Paragraph::new(Line::from(right)).style(Style::default().bg(status_bg)),
                Rect {
                    x: rx,
                    y: status_rect.y,
                    width: right_total,
                    height: status_rect.height,
                },
            );
            // Record hit rects: indices 1=indentation, 2=encoding, 3=EOL, 4=language.
            let mut cx = rx;
            for (i, w) in widths.iter().enumerate() {
                let r = Rect {
                    x: cx,
                    y: status_rect.y,
                    width: *w,
                    height: 1,
                };
                match i {
                    1 => self.status_indent_rect = r,
                    2 => self.status_encoding_rect = r,
                    3 => self.status_eol_rect = r,
                    4 => self.status_language_rect = r,
                    _ => {}
                }
                cx = cx.saturating_add(*w);
            }
        }

        // Overlays render last so they sit on top of everything else. The port
        // toast goes first so modals/menus paint above it.
        //
        // The hover note popup (editor symbol hover / terminal annotation
        // note) renders here against the WHOLE frame, not the editor's
        // focused_area: its anchor may sit in the terminal panel, and the
        // welcome screen skips the editor-tabs branch entirely, which used to
        // drop a terminal annotation's note without painting it at all.
        let hover_grad = self.popup_gradient();
        if let Some(popup) = self.hover_popup.as_mut() {
            popup.gradient = hover_grad;
            let area = popup.area_for(frame.area());
            if area.width > 0 && area.height > 0 {
                frame.render_widget(&*popup, area);
            }
        }
        self.render_port_toast(frame);
        self.render_context_menu(frame);
        self.render_commit_dropdown(frame);
        self.render_prompt(frame);
        self.render_local_open_confirm(frame);
        self.render_discard_confirm(frame);
        self.render_revert_hunk_confirm(frame);
        self.render_discard_all_confirm(frame);
        self.render_broadcast_confirm(frame);
        // Terminal-pane inline image: sync after the panes have painted so
        // last_inner and the scroll offset are this frame's (all gating —
        // hidden panel, alt screen, off-screen anchor — is inside).
        self.update_terminal_image_overlay();
        self.render_editor_find(frame);
        self.render_terminal_find(frame);
        self.render_file_finder(frame);
        self.render_command_palette(frame);
        self.render_go_to_symbol(frame);
        self.render_workspace_symbols(frame);
        self.render_process_picker(frame);
        self.render_zoxide_jump(frame);
        self.render_command_history_popup(frame);
        self.render_branch_picker(frame);
        self.render_scm_menu(frame);
        self.render_input_prompt(frame);
        self.render_list_picker(frame);
        self.render_shortcuts_modal(frame);
        self.render_connect_dialog(frame);
        // The startup unsupported-terminal nudge renders last so it sits above
        // every other overlay until the user dismisses it.
        self.render_terminal_warning(frame);

        // Chrome button-hint tooltip. Rendered at the top level against the
        // whole frame (not the editor's `focused_area`) because the controls it
        // labels live in the activity bar and sidebar, outside the editor pane;
        // clamping it to the editor area would yank it away from the control or,
        // on the welcome screen, drop it entirely.
        let tooltip_grad = self.popup_gradient();
        let mut tooltip_area = None;
        if let Some(popup) = self.ui_tooltip.as_mut() {
            popup.gradient = tooltip_grad;
            let full = frame.area();
            let mut area = popup.area_for(full);
            // Keep the box clear of the activity bar's inline-image column. Those
            // codicon glyphs are a terminal graphics layer that always composites
            // ABOVE text cells, so any overlap would paint over (hide) the left of
            // the tooltip. Shift it to the right of the bar instead, like VS Code
            // floats an activity-icon hint beside the icon.
            if area.x < ACTIVITY_BAR_WIDTH {
                area.x = ACTIVITY_BAR_WIDTH;
                area.width = area.width.min(full.width.saturating_sub(area.x));
            }
            if area.width > 0 && area.height > 0 {
                frame.render_widget(&*popup, area);
                tooltip_area = Some(area);
            }
        }
        // Record the box so the post-draw flush can RE-PAINT it on top of any
        // sidebar OSC-1337 illustration (the no-repo hero / SSH empty-state).
        // Those images are emitted after ratatui's text and would otherwise
        // composite over the tooltip; re-emitting the box last wins the cell.
        self.ui_tooltip_area = tooltip_area;

        // Show the host terminal's hardware caret only when the editor is
        // focused and has no modal overlay. The DECSCUSR style is set to
        // BlinkingBar at startup, so the terminal blinks a thin vertical
        // line over the cursor cell without replacing its character.
        if self.focus == Pane::Editor
            && self.context_menu.is_none()
            && self.prompt.is_none()
            && self.cursor_visible_phase()
        {
            let pos = if self.editor.diff.is_some() {
                self.editor.diff_caret_screen_pos()
            } else {
                self.editor.cursor_screen_pos()
            };
            if let Some((cx, cy)) = pos {
                frame.set_cursor_position((cx, cy));
            }
        }

        // Source-control commit-message caret. Same software-blink rule:
        // the user can't see where they're typing in the message box
        // without a visible caret, since `set_string` just lays the text
        // flat with no native caret cell.
        if self.focus == Pane::Tree
            && self.sidebar_view == SidebarView::SourceControl
            && self.context_menu.is_none()
            && self.prompt.is_none()
            && self.cursor_visible_phase()
            && let Some((cx, cy)) = self.source_control.cursor_screen_pos()
        {
            frame.set_cursor_position((cx, cy));
        }

        // Search-panel field caret and Extensions filter caret. Same software
        // blink as the commit box so all three side-panel inputs share one
        // blinking hardware caret instead of a static block (Search) or no
        // caret at all (Extensions).
        if self.focus == Pane::Tree
            && self.sidebar_view == SidebarView::Search
            && self.context_menu.is_none()
            && self.prompt.is_none()
            && self.cursor_visible_phase()
            && let Some((cx, cy)) = self.search.cursor_screen_pos()
        {
            frame.set_cursor_position((cx, cy));
        }
        if self.focus == Pane::Tree
            && self.sidebar_view == SidebarView::Extensions
            && self.context_menu.is_none()
            && self.prompt.is_none()
            && self.cursor_visible_phase()
            && let Some((cx, cy)) = self.extensions.cursor_screen_pos()
        {
            frame.set_cursor_position((cx, cy));
        }
    }

    fn render_context_menu(&self, frame: &mut ratatui::Frame) {
        let Some(menu) = &self.context_menu else {
            return;
        };
        // `menu_rect` already clamps against `last_frame_area`, so the
        // rect we draw here is the same rect `menu_item_at` hit-tests
        // against. Keeping the two in lock-step is what prevents the
        // off-by-N row dispatch when the menu has to shift up to fit.
        let Some(clipped) = self.menu_rect() else {
            return;
        };
        let grad = self.popup_gradient();
        // The top-level panel; the open submenu's parent row stays highlighted.
        self.render_menu_panel(frame, clipped, &menu.items, menu.selected, grad);
        // Float the open submenu's panel beside its parent.
        if let Some(sub_rect) = self.submenu_rect()
            && let Some(MenuEntry::Submenu { items, .. }) =
                menu.open_submenu.and_then(|p| menu.items.get(p))
        {
            self.render_menu_panel(frame, sub_rect, items, menu.submenu_selected, grad);
        }
    }

    /// Paint one bordered menu panel of `entries` into `rect`, highlighting row
    /// `selected`. Items show a right-aligned shortcut hint, submenu parents a
    /// `▸`, and separators a divider rule. Shared by the main menu and the
    /// floating submenu.
    fn render_menu_panel(
        &self,
        frame: &mut ratatui::Frame,
        rect: Rect,
        entries: &[MenuEntry],
        selected: usize,
        grad: bool,
    ) {
        // Black theme: orange→green gradient border + muted dark-teal
        // selection. Croft Dark keeps the legacy bright-blue accent so the
        // menu stays coherent with that theme's blue focus border.
        let border_blue = Color::Rgb(0x4e, 0x9a, 0xff);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(border_blue))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        if grad {
            paint_gradient_box(frame.buffer_mut(), rect);
        }
        let sel_bg = if grad {
            rgb_color(POPUP_SEL_BG)
        } else {
            border_blue
        };
        let sel_fg = if grad { Color::White } else { Color::Black };
        let inner = Rect {
            x: rect.x + 1,
            y: rect.y + 1,
            width: rect.width.saturating_sub(2),
            height: rect.height.saturating_sub(2),
        };
        for (i, entry) in entries.iter().enumerate() {
            if i as u16 >= inner.height {
                break;
            }
            let row = Rect {
                x: inner.x,
                y: inner.y + i as u16,
                width: inner.width,
                height: 1,
            };
            if let MenuEntry::Separator = entry {
                let rule = "\u{2500}".repeat(inner.width as usize);
                frame.buffer_mut().set_string(
                    inner.x,
                    row.y,
                    &rule,
                    Style::default().fg(Color::Rgb(0x45, 0x45, 0x45)),
                );
                continue;
            }
            if let MenuEntry::Header(label) = entry {
                // Dimmed, non-selectable section label (VS Code's group titles
                // like "Side Bar Position").
                frame.buffer_mut().set_string(
                    inner.x,
                    row.y,
                    format!(" {label}"),
                    Style::default()
                        .fg(Color::Rgb(0x7a, 0x82, 0x90))
                        .add_modifier(Modifier::BOLD),
                );
                continue;
            }
            let is_sel = i == selected;
            let row_style = if is_sel {
                Style::default().fg(sel_fg).bg(sel_bg)
            } else {
                Style::default().fg(Color::White)
            };
            let (label, right_hint) = match entry {
                MenuEntry::Item { label, action } => {
                    (label.as_str(), shortcut_for(action).map(str::to_string))
                }
                // A submenu parent shows the ▸ where a shortcut would sit.
                MenuEntry::Submenu { label, .. } => {
                    (label.as_str(), Some(String::from("\u{25b8}")))
                }
                MenuEntry::Separator | MenuEntry::Header(_) => {
                    unreachable!("handled above")
                }
            };
            let line = ratatui::text::Line::from(format!(" {label}"));
            frame.render_widget(ratatui::widgets::Paragraph::new(line).style(row_style), row);
            if let Some(hint) = right_hint {
                let hint_w = hint.chars().count() as u16;
                if hint_w + 2 <= inner.width {
                    let hint_x = inner.x + inner.width - hint_w - 1;
                    let hint_style = if is_sel {
                        Style::default().fg(sel_fg).bg(sel_bg)
                    } else {
                        Style::default().fg(Color::Rgb(0x9d, 0xa5, 0xb4))
                    };
                    frame
                        .buffer_mut()
                        .set_string(hint_x, row.y, &hint, hint_style);
                }
            }
        }
    }

    fn render_commit_dropdown(&mut self, frame: &mut ratatui::Frame) {
        use crate::widgets::source_control::CommitMenuItem;
        // The dropdown belongs to the Source Control view only. Gate on it
        // so a stale `commit_menu_open` flag can never paint the menu over
        // another sidebar view (e.g. Run-Debug) after a view switch.
        if !self.commit_menu_open || self.sidebar_view != SidebarView::SourceControl {
            self.source_control.commit_menu_item_areas.clear();
            return;
        }
        let caret = self.source_control.last_commit_caret_area;
        let main = self.source_control.last_button_area;
        if caret.width == 0 || main.width == 0 {
            return;
        }
        let default_branch = self
            .default_branch_label
            .clone()
            .unwrap_or_else(|| "default".to_string());
        let items: Vec<(CommitMenuItem, String)> = CommitMenuItem::ALL
            .iter()
            .map(|item| (*item, item.label(&default_branch)))
            .collect();
        // Row layout: [pad][icon][gap][label][pad]. The icon occupies one
        // cell at item_x+1; the label starts two cells later at item_x+3.
        const ICON_PAD: u16 = 3;
        let label_w = items
            .iter()
            .map(|(_, l)| l.chars().count() as u16 + ICON_PAD + 1)
            .max()
            .unwrap_or(0);
        let item_w: u16 = label_w.max(caret.width);
        let item_x = (caret.x + caret.width).saturating_sub(item_w).max(main.x);
        let item_y_top = caret.y + caret.height;
        let menu_rect = Rect {
            x: item_x,
            y: item_y_top,
            width: item_w,
            height: items.len() as u16,
        };
        let bg = Color::Rgb(0x25, 0x2b, 0x37);
        let fg = Color::White;
        let style = Style::default().fg(fg).bg(bg);
        frame.render_widget(ratatui::widgets::Clear, menu_rect);
        self.source_control.commit_menu_item_areas.clear();
        for (i, (item, label)) in items.into_iter().enumerate() {
            let row_y = item_y_top + i as u16;
            let row_rect = Rect {
                x: item_x,
                y: row_y,
                width: item_w,
                height: 1,
            };
            for rx in 0..row_rect.width {
                frame.buffer_mut()[(row_rect.x + rx, row_rect.y)]
                    .set_symbol(" ")
                    .set_style(style);
            }
            // Leading codicon, colored per action: push glyphs in blue,
            // diff/compare glyphs in purple, mirroring VS Code's SCM accents.
            let icon_color = match item {
                CommitMenuItem::CommitAndPush => Color::Rgb(0x9a, 0xa4, 0xb2),
                CommitMenuItem::Push | CommitMenuItem::Pull | CommitMenuItem::Sync => {
                    Color::Rgb(0x6c, 0xb6, 0xff)
                }
                CommitMenuItem::CheckoutBranch => Color::Rgb(0x88, 0xc0, 0xd0),
                CommitMenuItem::Stash | CommitMenuItem::StashPop => Color::Rgb(0xeb, 0xcb, 0x8b),
                CommitMenuItem::ViewStagedDiff
                | CommitMenuItem::ViewPreviousCommitDiff
                | CommitMenuItem::ViewDefaultBranchDiff => Color::Rgb(0xc0, 0xa4, 0xf5),
            };
            frame.buffer_mut().set_string(
                row_rect.x + 1,
                row_rect.y,
                item.icon().to_string(),
                Style::default().fg(icon_color).bg(bg),
            );
            frame
                .buffer_mut()
                .set_string(row_rect.x + 3, row_rect.y, &label, style);
            self.source_control
                .commit_menu_item_areas
                .push((row_rect, item));
        }
    }

    fn dispatch_commit_menu_item(&mut self, item: crate::widgets::source_control::CommitMenuItem) {
        use crate::widgets::source_control::CommitMenuItem;
        match item {
            CommitMenuItem::CommitAndPush => self.commit_and_push_source_control(),
            CommitMenuItem::Push => self.push_source_control(),
            CommitMenuItem::Pull => self.pull_source_control(),
            CommitMenuItem::Sync => self.sync_source_control(),
            CommitMenuItem::CheckoutBranch => self.open_branch_picker(),
            CommitMenuItem::Stash => self.stash_source_control(),
            CommitMenuItem::StashPop => self.stash_pop_source_control(),
            CommitMenuItem::ViewStagedDiff => self.view_staged_diff_source_control(),
            CommitMenuItem::ViewPreviousCommitDiff => {
                self.view_previous_commit_diff_source_control()
            }
            CommitMenuItem::ViewDefaultBranchDiff => self.view_default_branch_diff_source_control(),
        }
    }

    fn render_discard_confirm(&self, frame: &mut ratatui::Frame) {
        let Some(pd) = self.pending_discard.as_ref() else {
            return;
        };
        let area = frame.area();
        let width = area.width.saturating_sub(8).clamp(50, 96);
        let height: u16 = 8;
        let x = (area.width.saturating_sub(width)) / 2 + area.x;
        let y = (area.height.saturating_sub(height)) / 2 + area.y;
        let rect = Rect {
            x,
            y,
            width,
            height,
        };
        let warn = Color::Rgb(0xe7, 0x70, 0x70);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(warn))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)))
            .title(ratatui::text::Span::styled(
                " DISCARD CHANGES? ",
                Style::default()
                    .fg(Color::White)
                    .bg(warn)
                    .add_modifier(Modifier::BOLD),
            ));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        let inner = Rect {
            x: rect.x + 2,
            y: rect.y + 1,
            width: rect.width.saturating_sub(4),
            height: rect.height.saturating_sub(2),
        };
        let warn_text = if pd.untracked {
            "This will permanently delete the file from disk."
        } else {
            "This will overwrite your local changes from HEAD."
        };
        let body = ratatui::text::Text::from(vec![
            ratatui::text::Line::from(ratatui::text::Span::styled(
                warn_text,
                Style::default().fg(Color::White),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(ratatui::text::Span::styled(
                truncate_for_display(&pd.rel_path, inner.width as usize),
                Style::default().fg(Color::Rgb(0xeb, 0xcb, 0x8b)),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(vec![
                ratatui::text::Span::styled(
                    "[Y]",
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("es, discard   "),
                ratatui::text::Span::styled(
                    "[N]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("o / Esc"),
            ]),
        ]);
        frame.render_widget(ratatui::widgets::Paragraph::new(body), inner);
    }

    /// Confirmation modal for Revert Hunk: destroys the uncommitted edit
    /// under the diff caret, so it gets the same red Y/N gate as discard.
    fn render_revert_hunk_confirm(&self, frame: &mut ratatui::Frame) {
        let Some(pr) = self.pending_revert_hunk.as_ref() else {
            return;
        };
        let area = frame.area();
        let width = area.width.saturating_sub(8).clamp(50, 96);
        let height: u16 = 8;
        let x = (area.width.saturating_sub(width)) / 2 + area.x;
        let y = (area.height.saturating_sub(height)) / 2 + area.y;
        let rect = Rect {
            x,
            y,
            width,
            height,
        };
        let warn = Color::Rgb(0xe7, 0x70, 0x70);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(warn))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)))
            .title(ratatui::text::Span::styled(
                " REVERT HUNK? ",
                Style::default()
                    .fg(Color::White)
                    .bg(warn)
                    .add_modifier(Modifier::BOLD),
            ));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        let inner = Rect {
            x: rect.x + 2,
            y: rect.y + 1,
            width: rect.width.saturating_sub(4),
            height: rect.height.saturating_sub(2),
        };
        let body = ratatui::text::Text::from(vec![
            ratatui::text::Line::from(ratatui::text::Span::styled(
                "This will undo the change hunk under the cursor on disk.",
                Style::default().fg(Color::White),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(ratatui::text::Span::styled(
                truncate_for_display(&pr.rel_path, inner.width as usize),
                Style::default().fg(Color::Rgb(0xeb, 0xcb, 0x8b)),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(vec![
                ratatui::text::Span::styled(
                    "[Y]",
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("es, revert   "),
                ratatui::text::Span::styled(
                    "[N]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("o / Esc"),
            ]),
        ]);
        frame.render_widget(ratatui::widgets::Paragraph::new(body), inner);
    }

    /// Confirmation modal for "Discard All Changes" — reverts every tracked
    /// edit to HEAD, so it gets the same red Y/N gate as a single discard.
    fn render_discard_all_confirm(&self, frame: &mut ratatui::Frame) {
        if !self.pending_discard_all {
            return;
        }
        let area = frame.area();
        let width = area.width.saturating_sub(8).clamp(50, 96);
        let height: u16 = 7;
        let rect = Rect {
            x: (area.width.saturating_sub(width)) / 2 + area.x,
            y: (area.height.saturating_sub(height)) / 2 + area.y,
            width,
            height,
        };
        let warn = Color::Rgb(0xe7, 0x70, 0x70);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(warn))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)))
            .title(ratatui::text::Span::styled(
                " DISCARD ALL CHANGES? ",
                Style::default()
                    .fg(Color::White)
                    .bg(warn)
                    .add_modifier(Modifier::BOLD),
            ));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        let inner = Rect {
            x: rect.x + 2,
            y: rect.y + 1,
            width: rect.width.saturating_sub(4),
            height: rect.height.saturating_sub(2),
        };
        let body = ratatui::text::Text::from(vec![
            ratatui::text::Line::from(ratatui::text::Span::styled(
                "This reverts every tracked file to HEAD. Untracked files are kept.",
                Style::default().fg(Color::White),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(vec![
                ratatui::text::Span::styled(
                    "[Y]",
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("es, discard all   "),
                ratatui::text::Span::styled(
                    "[N]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("o / Esc"),
            ]),
        ]);
        frame.render_widget(ratatui::widgets::Paragraph::new(body), inner);
    }

    /// Confirmation modal for enabling broadcast input: the classic footgun
    /// is typing a destructive command into panes you forgot were listening,
    /// so switching it on gets the same red Y/N gate iTerm2 shows.
    fn render_broadcast_confirm(&self, frame: &mut ratatui::Frame) {
        if !self.pending_broadcast_enable {
            return;
        }
        let area = frame.area();
        let width = area.width.saturating_sub(8).clamp(50, 96);
        let height: u16 = 7;
        let rect = Rect {
            x: (area.width.saturating_sub(width)) / 2 + area.x,
            y: (area.height.saturating_sub(height)) / 2 + area.y,
            width,
            height,
        };
        let warn = Color::Rgb(0xe7, 0x70, 0x70);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(warn))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)))
            .title(ratatui::text::Span::styled(
                " BROADCAST INPUT TO ALL PANES? ",
                Style::default()
                    .fg(Color::White)
                    .bg(warn)
                    .add_modifier(Modifier::BOLD),
            ));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        let inner = Rect {
            x: rect.x + 2,
            y: rect.y + 1,
            width: rect.width.saturating_sub(4),
            height: rect.height.saturating_sub(2),
        };
        let receiving = self
            .terminals
            .iter()
            .filter(|t| !t.broadcast_excluded)
            .count()
            .max(1);
        let body = ratatui::text::Text::from(vec![
            ratatui::text::Line::from(ratatui::text::Span::styled(
                format!(
                    "Every keystroke and paste will go to {receiving} terminal panes at once (red \u{21f6} pills mark them). Cmd+K I stops it; Cmd+K Shift+I excludes a pane."
                ),
                Style::default().fg(Color::White),
            )),
            ratatui::text::Line::from(""),
            ratatui::text::Line::from(vec![
                ratatui::text::Span::styled(
                    "[Y]",
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("es, broadcast   "),
                ratatui::text::Span::styled(
                    "[N]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                ratatui::text::Span::raw("o / Esc"),
            ]),
        ]);
        frame.render_widget(
            ratatui::widgets::Paragraph::new(body).wrap(ratatui::widgets::Wrap { trim: true }),
            inner,
        );
    }

    fn render_terminal_warning(&self, frame: &mut ratatui::Frame) {
        if !self.pending_terminal_warning {
            return;
        }
        let area = frame.area();
        let width = area.width.saturating_sub(8).clamp(50, 96);
        let height: u16 = 11;
        let x = (area.width.saturating_sub(width)) / 2 + area.x;
        let y = (area.height.saturating_sub(height)) / 2 + area.y;
        let rect = Rect {
            x,
            y,
            width,
            height,
        };
        let warn = Color::Rgb(0xff, 0xa5, 0x00);
        let accent = Color::Rgb(0x4e, 0x9a, 0xff);
        let block = ratatui::widgets::Block::default()
            .borders(ratatui::widgets::Borders::ALL)
            .border_style(Style::default().fg(warn))
            .style(Style::default().bg(Color::Rgb(0x1e, 0x1e, 0x1e)))
            .title(ratatui::text::Span::styled(
                " UNSUPPORTED TERMINAL ",
                Style::default()
                    .fg(Color::Black)
                    .bg(warn)
                    .add_modifier(Modifier::BOLD),
            ));
        frame.render_widget(ratatui::widgets::Clear, rect);
        frame.render_widget(block, rect);
        let inner = Rect {
            x: rect.x + 2,
            y: rect.y + 1,
            width: rect.width.saturating_sub(4),
            height: rect.height.saturating_sub(2),
        };
        let current = std::env::var("TERM_PROGRAM")
            .ok()
            .filter(|s| !s.is_empty())
            .or_else(|| std::env::var("TERM").ok().filter(|s| !s.is_empty()))
            .unwrap_or_else(|| String::from("this terminal"));
        let body = ratatui::text::Text::from(vec![
            Line::from(Span::styled(
                "Croft draws its icons and images with inline-image protocols",
                Style::default().fg(Color::White),
            )),
            Line::from(Span::styled(
                format!("that {current} does not support, so the activity bar and"),
                Style::default().fg(Color::White),
            )),
            Line::from(Span::styled(
                "file icons stay blank. Croft still runs; for the full UI use:",
                Style::default().fg(Color::White),
            )),
            Line::from(""),
            Line::from(vec![
                Span::raw("  macOS:  "),
                Span::styled(
                    "iTerm2",
                    Style::default().fg(accent).add_modifier(Modifier::BOLD),
                ),
                Span::raw("  or  "),
                Span::styled(
                    "Ghostty",
                    Style::default().fg(accent).add_modifier(Modifier::BOLD),
                ),
            ]),
            Line::from(vec![
                Span::raw("  Linux:  "),
                Span::styled(
                    "Ghostty",
                    Style::default().fg(accent).add_modifier(Modifier::BOLD),
                ),
            ]),
            Line::from(""),
            Line::from(vec![
                Span::styled(
                    "[any key]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                Span::raw(" dismiss    "),
                Span::styled(
                    "[D]",
                    Style::default()
                        .fg(Color::Green)
                        .add_modifier(Modifier::BOLD),
                ),
                Span::raw("on't show again"),
            ]),
        ]);
        frame.render_widget(ratatui::widgets::Paragraph::new(body), inner);
    }

