    /// Spawn `pdb -p <pid>` for the chosen target in a new PTY terminal,
    /// wrapping in `sudo` when the platform requires elevation (always on
    /// macOS; on Linux unless Yama `ptrace_scope` is relaxed). The PTY hosts
    /// both the interactive pdb prompt and any `sudo` password prompt — the
    /// edge a GUI debugger lacks.
    fn attach_to_python_target(&mut self, target: crate::dap::discovery::PyTarget) {
        use crate::dap::remote_attach::{Platform, plan_attach, read_yama_ptrace_scope};
        let pid = target.pid;
        let plan = match plan_attach(
            target.version,
            target.exe,
            pid,
            Platform::current(),
            read_yama_ptrace_scope(),
        ) {
            Ok(plan) => plan,
            Err(e) => {
                self.run_debug.feedback = Some(format!("Cannot attach to PID {pid}: {e:?}"));
                self.run_debug.feedback_is_error = true;
                return;
            }
        };
        let (program, args) = plan.command_line();
        match PtyTerminal::new_running(&program, &args, &self.workspace_root) {
            Ok(term) => {
                let slot = self.active_terminal + 1;
                self.terminals.insert(slot, term);
                self.active_terminal = slot;
                if !self.show_terminal {
                    self.show_terminal = true;
                }
                self.focus_pane(Pane::Terminal);
                self.run_debug.feedback = Some(format!("Attaching debugger to PID {pid}"));
                self.run_debug.feedback_is_error = false;
            }
            Err(e) => {
                self.run_debug.feedback = Some(format!("Failed to spawn terminal: {e}"));
                self.run_debug.feedback_is_error = true;
            }
        }
    }

    /// Dispatch a chosen palette row: a built-in command runs inline; an
    /// extension-contributed command routes through the MCP sidecar path.
    fn run_palette_item(&mut self, item: crate::widgets::command_palette::PaletteItem) {
        use crate::widgets::command_palette::PaletteItem;
        match item {
            PaletteItem::Builtin(cmd) => self.run_command(cmd),
            PaletteItem::Extension(ec) => self.run_extension_command(&ec.id),
        }
    }

    /// Invoke an MCP sidecar command by id. Gated by first-run consent (a popup
    /// showing the exact spawn command); once consented, collects the declared
    /// argument (if any) via an input popup, then spawns the server off-thread.
    fn run_extension_command(&mut self, command_id: &str) {
        use crate::widgets::input_prompt::{InputPrompt, InputPurpose};
        let Some(resolved) = crate::mcp::registry::resolve_command(command_id) else {
            self.status = format!("Extension command '{command_id}' is unavailable");
            return;
        };
        // First-run consent gate: never spawn a sidecar until the user has
        // approved this extension, shown the exact command line croft will run.
        let consented = crate::prefs::Prefs::load_or_default()
            .mcp_consented
            .contains(&resolved.ext_id);
        if !consented {
            let spawn_line = std::iter::once(resolved.server.command.clone())
                .chain(resolved.server.args.iter().cloned())
                .collect::<Vec<_>>()
                .join(" ");
            self.open_input_prompt(
                InputPrompt::new(
                    InputPurpose::McpConsent {
                        command_id: command_id.to_string(),
                    },
                    format!("Allow {} to run:  {}", resolved.ext_id, spawn_line),
                    "Enter to allow · Esc to cancel",
                )
                .with_value("allow"),
            );
            return;
        }
        // Collect the declared argument, if any, then run.
        if let (Some(_), Some(label)) = (resolved.arg.as_ref(), resolved.prompt.as_ref()) {
            self.open_input_prompt(InputPrompt::new(
                InputPurpose::McpArg {
                    command_id: command_id.to_string(),
                },
                resolved.title.clone(),
                label.clone(),
            ));
            return;
        }
        self.spawn_mcp_command(resolved, None);
    }

    /// Spawn the MCP server off the UI thread and run the command's tool; the
    /// result is delivered to [`poll_mcp`](Self::poll_mcp) over a channel and
    /// rendered into a markdown scratch buffer. Refuses to start a second
    /// command while one is in flight.
    fn spawn_mcp_command(
        &mut self,
        resolved: crate::mcp::registry::ResolvedCommand,
        arg: Option<String>,
    ) {
        if self.mcp_rx.is_some() {
            self.status = String::from("An extension command is already running");
            return;
        }
        let (tx, rx) = std::sync::mpsc::channel();
        self.mcp_rx = Some(rx);
        // On first use the server isn't provisioned yet; the worker installs it
        // (block-and-wait) before running, which can take a moment. Say so, so
        // the user sees install progress rather than a silent "Running".
        let installing = resolved.server.provision.as_ref().is_some_and(|p| {
            crate::lsp::install::provisioned_command(&resolved.server.id, p).is_none()
        });
        let label = if installing {
            format!(
                "Installing {} (first run, this can take a moment)",
                resolved.title
            )
        } else {
            format!("Running {}", resolved.title)
        };
        // Drive the status-bar spinner badge while the worker runs.
        self.mcp_started = Some(std::time::Instant::now());
        self.mcp_busy_label = Some(label.clone());
        self.status = label.clone();
        let cwd = self.workspace_root.clone();
        let version = env!("CARGO_PKG_VERSION").to_string();
        let _ = std::thread::Builder::new()
            .name("mcp-cmd".into())
            .spawn(move || {
                let _ = tx.send(run_mcp_command_blocking(&resolved, arg, &cwd, &version));
            });
    }

    /// On-disk path for a scratch buffer (MCP output, Git Output): anchored under
    /// the workspace root with a filesystem-safe name, so Cmd+S saves it
    /// predictably into the open project (and the Explorer tree shows it) instead
    /// of writing a bare filename to croft's working directory.
    fn scratch_buffer_path(&self, name: &str) -> PathBuf {
        let safe = name.replace(['/', '\\'], "-");
        self.workspace_root.join(safe)
    }

    /// Drain a completed MCP command: render its text into a scratch buffer on
    /// success, or surface the error in the status line. Returns whether a
    /// redraw is needed. Called each frame from the main loop.
    pub fn poll_mcp(&mut self) -> bool {
        let Some(rx) = self.mcp_rx.as_ref() else {
            return false;
        };
        let outcome = match rx.try_recv() {
            Ok(o) => o,
            Err(std::sync::mpsc::TryRecvError::Empty) => return false,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                self.mcp_rx = None;
                self.mcp_started = None;
                self.mcp_busy_label = None;
                return false;
            }
        };
        self.mcp_rx = None;
        self.mcp_started = None;
        self.mcp_busy_label = None;
        match outcome.body {
            Ok(text) => {
                let label = self.scratch_buffer_path(&format!("{}.md", outcome.title));
                if self.editor.open_text_buffer(&label, &text).is_ok() {
                    self.focus_pane(Pane::Editor);
                    self.status = format!(
                        "{}: opened in a new tab — Cmd+S saves it into the project",
                        outcome.title
                    );
                }
            }
            Err(e) => {
                self.status = format!("{}: {e}", outcome.title);
            }
        }
        true
    }

    /// Execute a Command Palette entry. Editor text commands act on the active
    /// editor buffer; view / navigation commands defer to the same methods
    /// their dedicated chords use, so the palette can never drift from the
    /// keyboard surface.
    fn run_command(&mut self, cmd: crate::widgets::command_palette::Command) {
        use crate::widgets::command_palette::Command as Cmd;
        use crate::widgets::editor::CaseTransform;
        match cmd {
            Cmd::MoveLineUp => self.editor.move_lines_up(),
            Cmd::MoveLineDown => self.editor.move_lines_down(),
            Cmd::ToggleLineComment => {
                if !self.editor.toggle_line_comment() {
                    self.status = String::from("Toggle Line Comment: no comment for this language");
                }
            }
            Cmd::ToggleBlockComment => {
                if !self.editor.toggle_block_comment() {
                    self.status =
                        String::from("Toggle Block Comment: no block comment for this language");
                }
            }
            Cmd::JoinLines => self.editor.join_lines(),
            Cmd::DeleteLine => self.delete_current_line(),
            Cmd::TransformUpper => self.editor.transform_selection_case(CaseTransform::Upper),
            Cmd::TransformLower => self.editor.transform_selection_case(CaseTransform::Lower),
            Cmd::TransformTitle => self.editor.transform_selection_case(CaseTransform::Title),
            Cmd::SortLinesAscending => self.editor.sort_lines(true),
            Cmd::SortLinesDescending => self.editor.sort_lines(false),
            Cmd::TrimTrailingWhitespace => {
                if self.editor.trim_trailing_whitespace() {
                    self.status = String::from("Trimmed trailing whitespace");
                }
            }
            Cmd::ToggleWordWrap => {
                self.editor.toggle_wrap();
                self.status = if self.editor.wrap_enabled() {
                    String::from("Word wrap: on")
                } else {
                    String::from("Word wrap: off")
                };
            }
            Cmd::AddCursorAbove => self.editor.add_cursor_above(),
            Cmd::AddCursorBelow => self.editor.add_cursor_below(),
            Cmd::AddSelectionToNextMatch => self.start_select_next_occurrence(),
            Cmd::JumpToBracket => {
                if !self.editor.jump_to_matching_bracket() {
                    self.status = String::from("Go to Bracket: no matching bracket");
                }
            }
            Cmd::SelectToBracket => {
                if !self.editor.select_to_matching_bracket() {
                    self.status = String::from("Select to Bracket: no matching bracket");
                }
            }
            Cmd::TransposeCharacters => self.editor.transpose_chars(),
            Cmd::IndentationToSpaces => {
                self.editor.indentation_to_spaces();
                self.status = String::from("Converted indentation to spaces");
            }
            Cmd::IndentationToTabs => {
                self.editor.indentation_to_tabs();
                self.status = String::from("Converted indentation to tabs");
            }
            Cmd::FormatDocument => self.start_format_document(),
            Cmd::ToggleFormatOnSave => self.toggle_format_on_save(),
            Cmd::ToggleAutoSave => self.toggle_auto_save(),
            Cmd::ToggleInlineBlame => self.toggle_inline_blame(),
            Cmd::ToggleInlayHints => self.toggle_inlay_hints(),
            Cmd::ToggleMarkdownPreview => self.toggle_markdown_preview(),
            Cmd::ToggleTerminalTimestamps => self.toggle_terminal_timestamps(),
            Cmd::SearchFromTerminal => self.search_from_last_terminal_command(),
            Cmd::RestoreSnapshot => self.restore_history_snapshot(),
            Cmd::QuickFix => self.start_code_action(),
            Cmd::ReplaceInFile => self.open_editor_replace(),
            Cmd::MergeAcceptCurrent => {
                self.resolve_merge_at_cursor(crate::merge::Resolution::Current)
            }
            Cmd::MergeAcceptIncoming => {
                self.resolve_merge_at_cursor(crate::merge::Resolution::Incoming)
            }
            Cmd::MergeAcceptBoth => self.resolve_merge_at_cursor(crate::merge::Resolution::Both),
            Cmd::StageHunk => self.stage_hunk_at_caret(),
            Cmd::UnstageHunk => self.unstage_hunk_at_caret(),
            Cmd::RevertHunk => self.request_revert_hunk_at_caret(),
            Cmd::ToggleFold => {
                let row = self.editor.cursor_row;
                self.editor.toggle_fold(row);
            }
            Cmd::FoldAll => self.editor.fold_all(),
            Cmd::UnfoldAll => self.editor.unfold_all(),
            Cmd::TrimFinalNewlines => {
                if self.editor.trim_final_newlines() {
                    self.status = String::from("Trimmed final newlines");
                }
            }
            Cmd::SaveFile => self.save(),
            Cmd::Undo => {
                self.status = if self.editor.undo() {
                    String::from("Undo")
                } else {
                    String::from("Nothing to undo")
                };
            }
            Cmd::Redo => {
                self.status = if self.editor.redo() {
                    String::from("Redo")
                } else {
                    String::from("Nothing to redo")
                };
            }
            Cmd::CloseEditor => {
                if self.editor.close_active() {
                    self.sync_open_file_poll_mtime();
                    self.collapse_split_if_empty();
                    self.status = String::from("Closed tab");
                }
            }
            Cmd::SplitEditor => self.split_editor(),
            Cmd::QuickOpen => self.open_file_finder(),
            Cmd::GoToSymbol => self.open_go_to_symbol(),
            Cmd::GoToWorkspaceSymbol => self.open_workspace_symbols(""),
            Cmd::ToggleVimMode => self.toggle_vim_mode(),
            Cmd::ShowExplorer => self.set_sidebar_view(SidebarView::Explorer),
            Cmd::ShowSearch => self.set_sidebar_view(SidebarView::Search),
            Cmd::ShowSourceControl => self.set_sidebar_view(SidebarView::SourceControl),
            Cmd::ShowRunDebug => self.set_sidebar_view(SidebarView::RunDebug),
            Cmd::ShowRemote => self.set_sidebar_view(SidebarView::Remote),
            Cmd::ShowExtensions => self.set_sidebar_view(SidebarView::Extensions),
            Cmd::ShowTesting => self.open_testing_view(),
            Cmd::RunTestAtCursor => self.run_test_at_cursor(),
            Cmd::DebugTestAtCursor => self.debug_test_at_cursor(),
            Cmd::ToggleSideBar => self.show_tree = !self.show_tree,
            Cmd::ToggleSecondarySideBar => self.toggle_secondary_side_bar(),
            Cmd::ToggleZenMode => self.toggle_zen_mode(),
            Cmd::ToggleTerminal => self.toggle_terminal(),
            Cmd::ToggleMinimap => self.toggle_minimap(),
            Cmd::NewTerminal => match self.split_terminal() {
                Ok(()) => {
                    self.status = format!("Split terminal: {} active", self.terminals.len());
                }
                Err(e) => {
                    self.status = format!("Split terminal failed: {e}");
                }
            },
            Cmd::StartDebugging => self.debug_start_or_continue(),
            Cmd::StopDebugging => self.debug_stop(),
            Cmd::PauseDebugging => self.debug_pause(),
            Cmd::RestartDebugging => self.debug_restart(),
            Cmd::ToggleBreakpoint => self.debug_toggle_breakpoint(),
            Cmd::EditLogpoint => self.debug_edit_logpoint(),
            Cmd::ShowIncomingCalls => self.request_call_hierarchy_at_cursor(true),
            Cmd::ShowOutgoingCalls => self.request_call_hierarchy_at_cursor(false),
            Cmd::EditBreakpointCondition => self.debug_edit_condition(),
            Cmd::StepOver => self.debug_step("next"),
            Cmd::ToggleRaisedExceptions => self.debug_toggle_raised_exceptions(),
            Cmd::AttachPythonProcess => self.open_attach_python_picker(),
            Cmd::ColorTheme => self.open_theme_picker(),
            Cmd::SessionParticipants => self.open_participants_picker(),
            Cmd::CollabCancelStream => self.collab_cancel_stream(),
            Cmd::AskNavigator => {
                let (range, selection) = match self.editor.selection_rows() {
                    Some(rows) => (rows, self.editor.selection_text()),
                    None => {
                        let row = self.editor.cursor_row;
                        ((row, row), String::new())
                    }
                };
                self.open_ask_navigator(range, selection);
            }
            Cmd::YieldToNavigator => self.yield_to_navigator(),
            Cmd::ToggleNavigator => self.toggle_navigator(),
            Cmd::ClearNavigatorNotes => self.clear_navigator_notes(),
            Cmd::ToggleProactiveNavigator => self.toggle_proactive_navigator(),
            Cmd::NextComment => self.cycle_comment_box(),
            Cmd::IgnoreComment => self.ignore_focused_comment(),
            Cmd::RunTask => self.open_run_task_picker(),
            Cmd::RunBuildTask => self.run_build_task(),
            Cmd::RerunLastTask => self.rerun_last_task(),
            Cmd::KeyboardShortcuts => self.open_shortcuts_modal(),
            Cmd::OpenSettings => self.open_settings_view(),
            Cmd::OpenSettingsJson => self
                .open_config_file_in_editor(crate::prefs::config_path(), ConfigFileSeed::Settings),
            Cmd::OpenKeybindingsJson => self.open_config_file_in_editor(
                crate::keymap::keybindings_path(),
                ConfigFileSeed::Keybindings,
            ),
            Cmd::ConfigureSnippets => self.open_config_file_in_editor(
                crate::snippets::snippets_path(),
                ConfigFileSeed::Snippets,
            ),
            Cmd::OpenTriggersJson => self.open_config_file_in_editor(
                crate::triggers::triggers_path(),
                ConfigFileSeed::Triggers,
            ),
        }
    }

    /// Open one of the JSON config files in the editor, creating it seeded with
    /// a helpful starter when it doesn't exist yet, then reload the in-memory
    /// copy so a subsequent save takes effect without a relaunch.
    fn open_config_file_in_editor(&mut self, path: std::path::PathBuf, seed: ConfigFileSeed) {
        if !path.exists() {
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            let contents = match seed {
                ConfigFileSeed::Settings => {
                    let prefs = crate::prefs::Prefs::load_or_default();
                    serde_json::to_string_pretty(&prefs).unwrap_or_else(|_| String::from("{}\n"))
                }
                ConfigFileSeed::Keybindings => crate::keymap::TEMPLATE.to_string(),
                ConfigFileSeed::Snippets => crate::snippets::TEMPLATE.to_string(),
                ConfigFileSeed::Triggers => crate::triggers::TEMPLATE.to_string(),
            };
            if let Err(e) = std::fs::write(&path, contents) {
                self.status = format!("Could not create {}: {e}", path.display());
                return;
            }
        }
        if let Some(idx) = self.editor.find_tab_with_path(&path) {
            self.editor.select(idx);
        } else if self.editor.open(&path).is_err() {
            self.status = format!("Could not open {}", path.display());
            return;
        }
        self.focus_pane(Pane::Editor);
        self.sync_open_file_poll_mtime();
        self.status = match seed {
            ConfigFileSeed::Settings => {
                String::from("Editing settings.json — save to apply on next launch")
            }
            ConfigFileSeed::Keybindings => String::from(
                "Editing keybindings.json — save, then reload keybindings from the palette",
            ),
            ConfigFileSeed::Snippets => {
                String::from("Editing snippets.json — save to apply immediately")
            }
            ConfigFileSeed::Triggers => {
                String::from("Editing triggers.json — save to apply immediately")
            }
        };
    }

    pub fn consume_zoxide_jump_image_clear(&mut self) -> bool {
        self.overlays.zoxide_jump_clear.consume()
    }

    /// Open the zoxide jump popup and seed it with the full frecency list
    /// (`zoxide query -l`), so it shows the user's top directories before
    /// they type anything — like pressing `j<Tab>` in the shell.
    fn open_zoxide_jump(&mut self) {
        if self.zoxide_jump.is_some() {
            return;
        }
        let mut jump = crate::widgets::zoxide_jump::ZoxideJump::new();
        jump.install_state = crate::zoxide::install_state();
        jump.termux = crate::iterm2_inline::detect_termux();
        jump.set_results(crate::zoxide::query(""));
        // Snapshot the full frecency list so the typo-tolerant fuzzy
        // fallback can rank against it without re-spawning zoxide on every
        // missed keystroke.
        jump.set_all_dirs(jump.results.clone());
        let status = if jump.available {
            format!(
                "Jump: {} directories — type to filter, Esc to close",
                jump.results.len()
            )
        } else {
            // Same honest copy as the popup body (single source of truth).
            format!(
                "Jump: {}",
                crate::widgets::zoxide_jump::unavailable_message(jump.install_state, jump.termux)
                    .trim_start()
            )
        };
        self.zoxide_jump = Some(jump);
        self.overlays.zoxide_jump_clear.request();
        self.status = status;
    }

    fn close_zoxide_jump(&mut self) {
        if self.zoxide_jump.take().is_some() {
            self.overlays.zoxide_jump_clear.request();
            self.overlays.activity.mark_dirty();
            self.overlays.welcome.mark_dirty();
            self.overlays.hero.mark_dirty();
            self.invalidate_editor_image_layouts();
            self.status.clear();
        }
    }

    /// Re-run `zoxide query` for the popup's current text and feed the
    /// ranked matches back to the widget. The one subprocess per keystroke
    /// is cheap (zoxide reads a small frecency DB; single-digit ms) and
    /// fires only on input, never on the render hot path.
    ///
    /// Two layers: the strict `zoxide query` is authoritative and handles
    /// the common case. Only when it returns zero matches for a non-empty
    /// needle does the typo-tolerant `fuzzy_rank` fallback run, ranking the
    /// cached frecency DB by edit distance so a transposition like `spilt`
    /// still finds `pr-split` (zoxide's own subsequence matcher cannot).
    /// The fallback is purely in-memory, so it never spawns zoxide twice.
    fn refresh_zoxide_results(&mut self) {
        let Some(jump) = self.zoxide_jump.as_mut() else {
            return;
        };
        let needle = jump.query.clone();
        // The background install may have advanced (Running -> Done/Failed)
        // since the popup opened; keep the unavailable message current.
        jump.install_state = crate::zoxide::install_state();
        match crate::zoxide::query(&needle) {
            Some(paths) if paths.is_empty() && !needle.trim().is_empty() => {
                let ranked = crate::zoxide::fuzzy_rank(&needle, &jump.all_dirs);
                if ranked.is_empty() {
                    jump.set_results(Some(Vec::new()));
                } else {
                    jump.set_approximate_results(ranked);
                }
            }
            other => jump.set_results(other),
        }
    }

    fn handle_zoxide_jump_key(&mut self, key: KeyEvent) {
        let Some(jump) = self.zoxide_jump.as_mut() else {
            return;
        };
        match (key.code, key.modifiers) {
            (KeyCode::Esc, _) => {
                self.close_zoxide_jump();
            }
            (KeyCode::Enter, _) => {
                let path = jump.selected_path().map(|p| p.to_path_buf());
                if let Some(path) = path {
                    self.close_zoxide_jump();
                    self.change_workspace_root(path);
                }
            }
            (KeyCode::Up, _) => jump.select_prev(),
            (KeyCode::Down, _) => jump.select_next(),
            (KeyCode::PageUp, _) => {
                for _ in 0..10 {
                    jump.select_prev();
                }
            }
            (KeyCode::PageDown, _) => {
                for _ in 0..10 {
                    jump.select_next();
                }
            }
            (KeyCode::Left, _) => jump.move_cursor_left(),
            (KeyCode::Right, _) => jump.move_cursor_right(),
            (KeyCode::Home, _) => jump.move_cursor_home(),
            (KeyCode::End, _) => jump.move_cursor_end(),
            (KeyCode::Backspace, _) => {
                jump.pop_char();
                self.refresh_zoxide_results();
            }
            (KeyCode::Delete, _) => {
                jump.delete_char();
                self.refresh_zoxide_results();
            }
            (KeyCode::Char(c), m) if !m.intersects(KeyModifiers::CONTROL | KeyModifiers::SUPER) => {
                jump.push_char(c);
                self.refresh_zoxide_results();
            }
            _ => {}
        }
    }

    fn handle_zoxide_jump_mouse(&mut self, m: MouseEvent) {
        let Some(jump) = self.zoxide_jump.as_mut() else {
            return;
        };
        let inside = rect_contains(jump.last_rect, m.column, m.row);
        match m.kind {
            MouseEventKind::ScrollDown => {
                for _ in 0..3 {
                    jump.select_next();
                }
            }
            MouseEventKind::ScrollUp => {
                for _ in 0..3 {
                    jump.select_prev();
                }
            }
            MouseEventKind::Down(MouseButton::Left) | MouseEventKind::Down(MouseButton::Right)
                if !inside =>
            {
                self.close_zoxide_jump();
            }
            _ => {}
        }
    }

    fn render_zoxide_jump(&mut self, frame: &mut ratatui::Frame) {
        let sidebar = self.last_sidebar_area;
        let full = frame.area();
        let gradient = self.popup_gradient();
        let Some(jump) = self.zoxide_jump.as_mut() else {
            return;
        };
        // Anchor the popup over the Explorer column (it is an Explorer
        // action), dropping from the sidebar's top-left. The sidebar is
        // narrow, so widen the box rightward over the editor for readable
        // paths, capped to the frame. When the sidebar is collapsed there
        // is nothing to anchor to, so fall back to a centered box.
        let rect = match sidebar {
            Some(side) if side.width >= 2 && side.height >= 4 => {
                let width = side
                    .width
                    .max(ZOXIDE_JUMP_MIN_WIDTH)
                    .min(full.width.saturating_sub(side.x));
                Rect {
                    x: side.x,
                    y: side.y,
                    width,
                    height: side.height,
                }
            }
            _ => fallback_popup_rect(full, 100),
        };
        crate::widgets::zoxide_jump::render_zoxide_jump(jump, rect, frame.buffer_mut(), gradient);
    }

    fn render_command_history_popup(&mut self, frame: &mut ratatui::Frame) {
        let full = frame.area();
        let gradient = self.popup_gradient();
        let Some(pop) = self.command_history_popup.as_mut() else {
            return;
        };
        // Centered box, the zoxide-jump fallback geometry: wide enough for
        // command lines, anchored in the upper half like Quick Open.
        let rect = fallback_popup_rect(full, 110);
        crate::widgets::history_popup::render_history_popup(
            pop,
            rect,
            frame.buffer_mut(),
            gradient,
        );
    }

    pub fn consume_branch_picker_image_clear(&mut self) -> bool {
        self.overlays.branch_picker_clear.consume()
    }

    /// Open the Checkout / Create Branch picker, seeded with the repo's
    /// branches (most-recently-committed first). A one-shot `git
    /// for-each-ref` runs here, off the render path — same discipline as
    /// the zoxide jumper. Outside a git repo there is nothing to pick, so
    /// we report that instead of opening an empty box.
    fn open_branch_picker(&mut self) {
        if self.branch_picker.is_some() {
            return;
        }
        self.commit_menu_open = false;
        match crate::git::list_branches(&self.tree.root) {
            Ok(branches) => {
                let n = branches.len();
                self.branch_picker =
                    Some(crate::widgets::branch_picker::BranchPicker::new(branches));
                self.overlays.branch_picker_clear.request();
                self.status =
                    format!("Branches: {n} — type to filter or name a new branch, Esc to close");
            }
            Err(err) => {
                self.source_control.commit_feedback = Some(format!("branches: {err}"));
                self.source_control.commit_feedback_is_error = true;
                self.status = format!("Branch picker: {err}");
            }
        }
    }

    fn close_branch_picker(&mut self) {
        if self.branch_picker.take().is_some() {
            self.overlays.branch_picker_clear.request();
            self.overlays.activity.mark_dirty();
            self.overlays.welcome.mark_dirty();
            self.overlays.hero.mark_dirty();
            self.invalidate_editor_image_layouts();
            self.status.clear();
        }
    }

    /// Run the action the highlighted picker row resolves to: switch to an
    /// existing branch, or create-and-switch a new one. The picker closes
    /// on success; on failure it stays open with the error in the SC
    /// feedback line so the user can amend the name.
    fn apply_branch_action(&mut self, action: crate::widgets::branch_picker::BranchAction) {
        use crate::widgets::branch_picker::BranchAction;
        let (result, verb) = match &action {
            BranchAction::Checkout(name) => (
                crate::git::checkout_branch(&self.tree.root, name),
                "Switched to",
            ),
            BranchAction::Create(name) => {
                (crate::git::create_branch(&self.tree.root, name), "Created")
            }
        };
        match result {
            Ok(summary) => {
                self.close_branch_picker();
                self.source_control.commit_feedback = Some(summary.clone());
                self.source_control.commit_feedback_is_error = false;
                self.status = format!("{verb}: {summary}");
                self.git.bypass_debounce();
                self.refresh_git_status_debounced();
                self.refresh_source_control();
            }
            Err(err) => {
                self.source_control.commit_feedback = Some(format!("branch: {err}"));
                self.source_control.commit_feedback_is_error = true;
                self.status = format!("Branch: {err}");
            }
        }
    }

    fn handle_branch_picker_key(&mut self, key: KeyEvent) {
        let Some(picker) = self.branch_picker.as_mut() else {
            return;
        };
        match (key.code, key.modifiers) {
            (KeyCode::Esc, _) => self.close_branch_picker(),
            (KeyCode::Enter, _) => self.apply_branch_picker_selection(),
            (KeyCode::Up, _) => picker.select_prev(),
            (KeyCode::Down, _) => picker.select_next(),
            (KeyCode::PageUp, _) => {
                for _ in 0..10 {
                    picker.select_prev();
                }
            }
            (KeyCode::PageDown, _) => {
                for _ in 0..10 {
                    picker.select_next();
                }
            }
            (KeyCode::Left, _) => picker.move_cursor_left(),
            (KeyCode::Right, _) => picker.move_cursor_right(),
            (KeyCode::Home, _) => picker.move_cursor_home(),
            (KeyCode::End, _) => picker.move_cursor_end(),
            (KeyCode::Backspace, _) => picker.pop_char(),
            (KeyCode::Delete, _) => picker.delete_char(),
            (KeyCode::Char(c), m) if !m.intersects(KeyModifiers::CONTROL | KeyModifiers::SUPER) => {
                picker.push_char(c);
            }
            _ => {}
        }
    }

    fn handle_branch_picker_mouse(&mut self, m: MouseEvent) {
        let Some(picker) = self.branch_picker.as_mut() else {
            return;
        };
        let inside = rect_contains(picker.last_rect, m.column, m.row);
        match m.kind {
            MouseEventKind::ScrollDown => {
                for _ in 0..3 {
                    picker.select_next();
                }
            }
            MouseEventKind::ScrollUp => {
                for _ in 0..3 {
                    picker.select_prev();
                }
            }
            MouseEventKind::Down(MouseButton::Left) | MouseEventKind::Down(MouseButton::Right)
                if !inside =>
            {
                self.close_branch_picker();
            }
            _ => {}
        }
    }

    fn render_branch_picker(&mut self, frame: &mut ratatui::Frame) {
        let sidebar = self.last_sidebar_area;
        let full = frame.area();
        let gradient = self.popup_gradient();
        let Some(picker) = self.branch_picker.as_mut() else {
            return;
        };
        // Anchor over the sidebar column like the jumper (it is a Source
        // Control action), widening rightward for readable branch names;
        // fall back to a centered box when the sidebar is collapsed.
        let rect = match sidebar {
            Some(side) if side.width >= 2 && side.height >= 4 => {
                let width = side
                    .width
                    .max(ZOXIDE_JUMP_MIN_WIDTH)
                    .min(full.width.saturating_sub(side.x));
                Rect {
                    x: side.x,
                    y: side.y,
                    width,
                    height: side.height,
                }
            }
            _ => fallback_popup_rect(full, 100),
        };
        crate::widgets::branch_picker::render_branch_picker(
            picker,
            rect,
            frame.buffer_mut(),
            gradient,
        );
    }

    pub fn consume_input_prompt_image_clear(&mut self) -> bool {
        self.overlays.input_prompt_clear.consume()
    }

    pub fn consume_list_picker_image_clear(&mut self) -> bool {
        self.overlays.list_picker_clear.consume()
    }

